// ─── CHARGEMENT FONTS + PHOSPHOR ────────────────────────
function useMariusAssets() {
  useEffect(() => {
    [
      { id:"ph-css",     href:"https://unpkg.com/@phosphor-icons/web@2.1.1/src/light/style.css" },
      { id:"inter-font", href:"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" },
      { id:"monts-font", href:"https://fonts.googleapis.com/css2?family=Montserrat:wght@700;800&display=swap" },
    ].forEach(({ id, href }) => {
      if (!document.getElementById(id)) {
        const l = document.createElement("link");
        l.rel = "stylesheet"; l.href = href; l.id = id;
        document.head.appendChild(l);
      }
    });
  }, []);
}

