function typeBadge(type: TypeQ) {
  const map: Record<TypeQ,{bg:string;color:string}> = {
    "Texte libre":    {bg:"#F2F3F4",color:"#2A5161"},
    "Nombre":         {bg:"#E6F3FA",color:"#2A5161"},
    "Oui / Non":      {bg:"#EBF4EC",color:"#388E3C"},
    "Choix multiple": {bg:"#F7E6FF",color:"#7A00B3"},
    "Signature":      {bg:"#F3F9EC",color:"#AC5700"},
  };
  const s = map[type];
  return <span style={{fontSize:"12px",fontWeight:500,padding:"2px 8px",borderRadius:"4px",background:s.bg,color:s.color,whiteSpace:"nowrap"}}>{type}</span>;
}

function ParametrageEnquete({ onBack }: { onBack: ()=>void }) {
  const [sections, setSections] = useState<SectionDef[]>(SECTIONS_INIT);
  const [saved, setSaved] = useState(false);

  const totalActives = sections.reduce((a,s)=>a+s.questions.filter(q=>q.active).length, 0);
  const totalQ       = sections.reduce((a,s)=>a+s.questions.length, 0);

  const toggleSection = (id:number) =>
    setSections(ss => ss.map(s => s.id===id ? {...s, open:!s.open} : s));

  const toggleQuestion = (sid:number, qid:number) =>
    setSections(ss => ss.map(s => s.id===sid
      ? {...s, questions: s.questions.map(q => q.id===qid ? {...q,active:!q.active} : q)}
      : s));

  return (
    <div style={{padding:"0"}}>
      {/* Header actions */}
      <div style={{padding:"16px 32px 0",display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:"4px"}}>
        <button onClick={onBack} style={{display:"flex",alignItems:"center",gap:"8px",background:"none",border:"none",cursor:"pointer",color:C.secondary,fontSize:"14px",fontWeight:500,padding:"0"}}>
          <i className="ph-light ph-arrow-left" style={{fontSize:"16px"}}/>
          Retour au suivi
        </button>
        <div style={{display:"flex",gap:"12px",alignItems:"center"}}>
          <button onClick={()=>{setSaved(true);setTimeout(()=>setSaved(false),2000)}}
            style={{display:"flex",alignItems:"center",gap:"8px",background:"#FFFFFF",border:"1px solid #D6D9DB",borderRadius:"4px",padding:"8px 16px",fontSize:"14px",fontWeight:500,color:C.primary,cursor:"pointer"}}>
            <i className="ph-light ph-floppy-disk" style={{fontSize:"14px"}}/>
            {saved ? "✓ Sauvegardé" : "Sauvegarder"}
          </button>
          <button style={{display:"flex",alignItems:"center",gap:"8px",background:"#FFFFFF",border:"1px solid #D6D9DB",borderRadius:"4px",padding:"8px 16px",fontSize:"14px",fontWeight:500,color:C.primary,cursor:"pointer"}}>
            <i className="ph-light ph-eye" style={{fontSize:"14px"}}/>
            Prévisualiser
          </button>
          <button style={{fontFamily:"Montserrat,sans-serif",display:"flex",alignItems:"center",gap:"8px",background:"#2E596B",border:"none",borderRadius:"4px",padding:"8px 16px",fontSize:"14px",fontWeight:600,color:"#FFFFFF",cursor:"pointer"}}>
            <i className="ph-light ph-paper-plane-tilt" style={{fontSize:"14px"}}/>
            Diffuser l'enquête
          </button>
        </div>
      </div>

      {/* Titre + compteur */}
      <div style={{padding:"16px 32px 24px",display:"flex",alignItems:"flex-start",justifyContent:"space-between",borderBottom:"1px solid #EAEEF0"}}>
        <div>
          <h4 style={{margin:"0 0 4px",fontWeight:700,color:C.primary,fontSize:"20px",fontFamily:"Montserrat,sans-serif"}}>Paramétrage de l'enquête sociale</h4>
          <p style={{margin:0,fontSize:"14px",color:"#587A89"}}>
            Configurez les questions avant diffusion aux copropriétaires de <strong style={{color:C.primary}}>{COPRO.nom}</strong>
          </p>
        </div>
        <div style={{textAlign:"right",flexShrink:0,marginLeft:"24px"}}>
          <div style={{fontSize:"12px",color:"#587A89",marginBottom:"2px"}}>Questions actives</div>
          <div style={{fontSize:"24px",fontWeight:700,color:C.primary,lineHeight:1}}>
            {totalActives}<span style={{fontSize:"14px",color:"#9FB3BB",fontWeight:400}}>/{totalQ}</span>
          </div>
        </div>
      </div>

      {/* Sections accordéon */}
      <div style={{padding:"16px 32px",display:"flex",flexDirection:"column",gap:"12px"}}>
        {sections.map(sec=>{
          const actives = sec.questions.filter(q=>q.active).length;
          return (
            <div key={sec.id} style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",overflow:"hidden"}}>
              {/* Section header */}
              <div
                onClick={()=>toggleSection(sec.id)}
                style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"12px 16px",cursor:"pointer",userSelect:"none",background:"#FBFBFB"}}>
                <div style={{display:"flex",alignItems:"center",gap:"12px"}}>
                  <i className={`ph-light ${sec.open?"ph-caret-down":"ph-caret-right"}`} style={{fontSize:"14px",color:"#9FB3BB"}}/>
                  <span style={{fontSize:"16px"}}>{sec.emoji}</span>
                  <span style={{fontWeight:600,color:C.primary,fontSize:"14px"}}>Section {sec.id} — {sec.title}</span>
                </div>
                <span style={{fontSize:"12px",color:"#9FB3BB",fontWeight:500}}>{actives}/{sec.questions.length} actives</span>
              </div>

              {/* Questions */}
              {sec.open && (
                <div>
                  {sec.questions.map(q=>(
                    <div key={q.id} style={{display:"flex",alignItems:"center",gap:"12px",padding:"12px 16px",borderTop:"1px solid #F2F3F4",transition:"background 0.1s"}}
                      onMouseEnter={e=>(e.currentTarget as HTMLElement).style.background="#FBFBFB"}
                      onMouseLeave={e=>(e.currentTarget as HTMLElement).style.background="transparent"}>
                      {/* Drag handle */}
                      <i className="ph-light ph-dots-six-vertical" style={{fontSize:"14px",color:"#BECCD1",cursor:"grab",flexShrink:0}}/>
                      {/* Checkbox */}
                      <input type="checkbox" checked={q.active} onChange={()=>toggleQuestion(sec.id,q.id)}
                        style={{width:"15px",height:"15px",accentColor:C.primary,cursor:"pointer",flexShrink:0}}/>
                      {/* Label */}
                      <span style={{flex:1,fontSize:"14px",color:q.active?C.primary:"#9FB3BB",fontWeight:400}}>
                        {q.label}
                        {q.required && <span style={{color:"#D32F2F",marginLeft:"4px",fontWeight:700}}>*</span>}
                        {q.hint && <span style={{fontSize:"12px",color:"#9FB3BB",marginLeft:"8px"}}>— {q.hint}</span>}
                      </span>
                      {/* Type badge */}
                      {typeBadge(q.type)}
                      {/* Actions */}
                      <button style={{background:"none",border:"none",cursor:"pointer",padding:"2px 4px",color:"#9FB3BB",fontSize:"14px",flexShrink:0}}>
                        <i className="ph-light ph-pencil-simple"/>
                      </button>
                      <button style={{background:"none",border:"none",cursor:"pointer",padding:"2px 4px",color:"#9FB3BB",fontSize:"14px",flexShrink:0}}>
                        <i className="ph-light ph-dots-three"/>
                      </button>
                    </div>
                  ))}
                  {/* Ajouter une question */}
                  <div style={{padding:"12px 16px",borderTop:"1px solid #F2F3F4"}}>
                    <button style={{display:"flex",alignItems:"center",gap:"8px",background:"none",border:"none",cursor:"pointer",color:C.secondary,fontSize:"14px",fontWeight:500,padding:0}}>
                      <i className="ph-light ph-plus" style={{fontSize:"14px"}}/>
                      Ajouter une question
                    </button>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

