// ── Rapport d'enquête sociale — vue inline (CS / Syndic, identique au contenu du modal AMO) ──
function RapportEnqueteSocialeInline() {
  const ok  = LOTS.filter(l=>l.statut==="répondu").length;
  const tm  = LOTS.filter(l=>l.qual==="très modeste").length;
  const mo  = LOTS.filter(l=>l.qual==="modeste").length;
  const in_ = LOTS.filter(l=>l.qual==="intermédiaire").length;
  const su  = LOTS.filter(l=>l.qual==="supérieur").length;
  const nq  = LOTS.filter(l=>l.qual==="inconnu").length;

  const repLots=LOTS.filter(l=>l.statut==="répondu").map(l=>SURVEY_RESPONSES[l.id]).filter(Boolean);
  const totalRep=repLots.length;
  if(totalRep===0) return <div style={{padding:"40px",textAlign:"center",color:"#9FB3BB",fontSize:"14px"}}>Aucune réponse enregistrée pour le moment.</div>;

  const soutienData=[
    {label:"Favorables",             val:repLots.filter(r=>r.soutien_renov==="oui").length,             c:"#388E3C",bg:"#F3F9EC"},
    {label:"Fav. avec réserves",     val:repLots.filter(r=>r.soutien_renov==="oui_avec_reserve").length, c:"#F7922B",bg:"#F7EBB7"},
    {label:"Neutres",                val:repLots.filter(r=>r.soutien_renov==="neutre").length,           c:"#587A89",bg:"#F2F3F4"},
    {label:"Défavorables",           val:repLots.filter(r=>r.soutien_renov==="non").length,              c:"#D32F2F",bg:"#FBEAEA"},
  ];
  const allIssues=repLots.flatMap(r=>r.issues);
  const issueCount=allIssues.reduce((acc,i)=>{acc[i]=(acc[i]||0)+1;return acc;},{} as Record<string,number>);
  const issuesSorted=Object.entries(issueCount).sort(([,a],[,b])=>b-a);
  const allFin=repLots.flatMap(r=>r.financement_pref);
  const finCount=allFin.reduce((acc,f)=>{acc[f]=(acc[f]||0)+1;return acc;},{} as Record<string,number>);
  const finSorted=Object.entries(finCount).sort(([,a],[,b])=>b-a);
  const avgOccupants=Math.round(repLots.reduce((s,r)=>s+r.occupants,0)/totalRep*10)/10;
  const dpeConnus=repLots.filter(r=>r.dpe_connaissance==="oui").length;
  const nbHandicap=repLots.filter(r=>r.handicap).length;
  const nbIsolement=repLots.filter(r=>r.isolement).length;
  const nbMonoparental=repLots.filter(r=>r.monoparental).length;
  const nbDiffFin=repLots.filter(r=>r.difficulte_financement).length;
  const nbChargesImp=repLots.filter(r=>r.charges_impayees).length;
  const avgRfr=Math.round(repLots.filter(r=>r.rfr>0).reduce((s,r)=>s+r.rfr,0)/repLots.filter(r=>r.rfr>0).length);
  const nbEnfants=repLots.reduce((s,r)=>s+r.enfants,0);

  return (
    <div style={{padding:"24px 32px",display:"flex",flexDirection:"column",gap:"24px",maxWidth:"900px"}}>
      {/* Titre */}
      <div style={{display:"flex",alignItems:"center",gap:"16px"}}>
        <div style={{width:"44px",height:"44px",borderRadius:"8px",background:"linear-gradient(135deg,#7A00B3,#7A00B3)",display:"flex",alignItems:"center",justifyContent:"center"}}>
          <i className="ph-light ph-chart-bar" style={{fontSize:"20px",color:"#FFFFFF"}}/>
        </div>
        <div>
          <div style={{fontWeight:700,color:C.primary,fontSize:"20px",fontFamily:"Montserrat,sans-serif"}}>Rapport d'Enquête Sociale</div>
          <div style={{fontSize:"12px",color:"#587A89"}}>La Résidence Vauban · Rénov'HdF · {new Date().toLocaleDateString("fr-FR",{day:"numeric",month:"long",year:"numeric"})}</div>
        </div>
        <div style={{marginLeft:"auto",background:"#F7E6FF",border:"1px solid #F7E6FF",borderRadius:"8px",padding:"8px 16px",textAlign:"center"}}>
          <div style={{fontSize:"24px",fontWeight:700,color:"#7A00B3",fontFamily:"Montserrat,sans-serif"}}>{Math.round(ok/LOTS.length*100)}%</div>
          <div style={{fontSize:"10px",color:"#7A00B3",fontWeight:700}}>Participation · {ok}/{LOTS.length} lots</div>
        </div>
      </div>

      {/* KPIs synthèse */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:"12px"}}>
        {[
          {l:"Occupation moyenne",v:`${avgOccupants} pers.`,sub:"par logement",c:"#2E596B",bg:"#E6F3FA",icon:"ph-users"},
          {l:"DPE connu",v:`${Math.round(dpeConnus/totalRep*100)}%`,sub:"des répondants",c:"#388E3C",bg:"#F3F9EC",icon:"ph-thermometer"},
          {l:"Favorables projet",v:`${Math.round(soutienData.slice(0,2).reduce((s,d)=>s+d.val,0)/totalRep*100)}%`,sub:"dont réserves",c:"#F7922B",bg:"#F7EBB7",icon:"ph-thumbs-up"},
          {l:"RFR moyen déclaré",v:`${(avgRfr/1000).toFixed(0)}k €`,sub:"Avis d'imposition",c:"#7A00B3",bg:"#F7E6FF",icon:"ph-currency-eur"},
        ].map(k=>(
          <div key={k.l} style={{background:k.bg,border:`1px solid ${k.c}20`,borderRadius:"8px",padding:"12px 16px"}}>
            <div style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
              <i className={`ph-light ${k.icon}`} style={{fontSize:"14px",color:k.c}}/>
              <span style={{fontSize:"10px",color:"#587A89",fontWeight:700}}>{k.l}</span>
            </div>
            <div style={{fontSize:"24px",fontWeight:700,color:k.c,fontFamily:"Montserrat,sans-serif",lineHeight:1}}>{k.v}</div>
            <div style={{fontSize:"10px",color:k.c+"99",marginTop:"4px"}}>{k.sub}</div>
          </div>
        ))}
      </div>

      {/* Grille 2 colonnes */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"16px"}}>
        {/* Qualification des ménages */}
        <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
          <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
            <i className="ph-light ph-users" style={{fontSize:"16px",color:"#7A00B3"}}/>Qualification des ménages
          </div>
          {([["très modeste",tm,"#D32F2F","#FBEAEA"],["modeste",mo,"#F57C00","#FEF2E6"],["intermédiaire",in_,"#2E596B","#E6F3FA"],["supérieur",su,"#388E3C","#F3F9EC"],["inconnu",nq,"#587A89","#F2F3F4"]] as [string,number,string,string][]).map(([label,val,c])=>{
            const pct=LOTS.length>0?Math.round(val/LOTS.length*100):0;
            return(
              <div key={label} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                <span style={{fontSize:"12px",color:"#2A5161",minWidth:"90px",textTransform:"capitalize"}}>{label}</span>
                <div style={{flex:1,height:"8px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                  <div style={{width:pct+"%",height:"100%",background:c,borderRadius:"999px"}}/>
                </div>
                <span style={{fontSize:"12px",fontWeight:700,color:c,minWidth:"28px",textAlign:"right"}}>{val}</span>
                <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"28px"}}>{pct}%</span>
              </div>
            );
          })}
        </div>

        {/* Position vis-à-vis du projet */}
        <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
          <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
            <i className="ph-light ph-thumbs-up" style={{fontSize:"16px",color:"#7A00B3"}}/>Position vis-à-vis du projet
          </div>
          {soutienData.map(s=>{
            const pct=totalRep>0?Math.round(s.val/totalRep*100):0;
            return(
              <div key={s.label} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                <span style={{fontSize:"12px",color:"#2A5161",minWidth:"115px"}}>{s.label}</span>
                <div style={{flex:1,height:"8px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                  <div style={{width:pct+"%",height:"100%",background:s.c,borderRadius:"999px"}}/>
                </div>
                <span style={{fontSize:"12px",fontWeight:700,color:s.c,minWidth:"20px",textAlign:"right"}}>{s.val}</span>
                <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"28px"}}>{pct}%</span>
              </div>
            );
          })}
        </div>

        {/* Problèmes constatés */}
        <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
          <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
            <i className="ph-light ph-warning-circle" style={{fontSize:"16px",color:"#F57C00"}}/>Problèmes les plus cités (Section 3)
          </div>
          {issuesSorted.map(([issue,count])=>{
            const pct=Math.round(count/totalRep*100);
            return(
              <div key={issue} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                <span style={{fontSize:"12px",color:"#2A5161",minWidth:"130px"}}>{issue}</span>
                <div style={{flex:1,height:"8px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                  <div style={{width:pct+"%",height:"100%",background:"#F57C00",borderRadius:"999px"}}/>
                </div>
                <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"36px",textAlign:"right"}}>{count} lots · {pct}%</span>
              </div>
            );
          })}
        </div>

        {/* Financement souhaité */}
        <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
          <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
            <i className="ph-light ph-bank" style={{fontSize:"16px",color:"#2E596B"}}/>Financement souhaité (Section 5)
          </div>
          {finSorted.map(([fin,count])=>{
            const pct=Math.round(count/totalRep*100);
            return(
              <div key={fin} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                <span style={{fontSize:"12px",color:"#2A5161",minWidth:"150px",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}} title={fin}>{fin}</span>
                <div style={{flex:1,height:"8px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                  <div style={{width:pct+"%",height:"100%",background:"#2E596B",borderRadius:"999px"}}/>
                </div>
                <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"36px",textAlign:"right"}}>{count} lots</span>
              </div>
            );
          })}
        </div>
      </div>

      {/* Indicateurs de fragilité sociale */}
      <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
        <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
          <i className="ph-light ph-shield-warning" style={{fontSize:"16px",color:"#F57C00"}}/>Indicateurs de fragilité sociale (Section 3)
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"12px",marginBottom:"12px"}}>
          {[
            {l:"RFR moyen déclaré",        v:`${avgRfr.toLocaleString("fr-FR")} €`, c:"#7A00B3",bg:"#F7E6FF",icon:"ph-currency-eur"},
            {l:"Enfants à charge (total)",  v:`${nbEnfants} enfants`,                c:"#2E596B",bg:"#E6F3FA",icon:"ph-baby"},
            {l:"Propriétaires occupants",   v:`${repLots.filter(r=>r.statut_occu.startsWith("Propriétaire occupant")).length}/${totalRep}`, c:"#388E3C",bg:"#F3F9EC",icon:"ph-house"},
          ].map(k=>(
            <div key={k.l} style={{background:k.bg,border:`1px solid ${k.c}20`,borderRadius:"8px",padding:"12px 12px"}}>
              <div style={{display:"flex",alignItems:"center",gap:"4px",marginBottom:"4px"}}>
                <i className={`ph-light ${k.icon}`} style={{fontSize:"14px",color:k.c}}/>
                <span style={{fontSize:"10px",color:"#587A89",fontWeight:700}}>{k.l}</span>
              </div>
              <div style={{fontSize:"16px",fontWeight:700,color:k.c,fontFamily:"Montserrat,sans-serif"}}>{k.v}</div>
            </div>
          ))}
        </div>
        {[
          {label:"Handicap déclaré",                    val:nbHandicap,    c:"#7A00B3"},
          {label:"Isolement social",                     val:nbIsolement,   c:"#F57C00"},
          {label:"Famille monoparentale",               val:nbMonoparental,c:"#2E596B"},
          {label:"Difficultés à financer la quote-part",val:nbDiffFin,     c:"#D32F2F"},
          {label:"Charges copropriété impayées",         val:nbChargesImp,  c:"#F7922B"},
        ].map(s=>{
          const pct=totalRep>0?Math.round(s.val/totalRep*100):0;
          return(
            <div key={s.label} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
              <span style={{fontSize:"12px",color:"#2A5161",minWidth:"220px"}}>{s.label}</span>
              <div style={{flex:1,height:"7px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                <div style={{width:pct+"%",height:"100%",background:s.c,borderRadius:"999px"}}/>
              </div>
              <span style={{fontSize:"12px",fontWeight:700,color:s.c,minWidth:"22px",textAlign:"right"}}>{s.val}</span>
              <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"32px"}}>{pct}%</span>
            </div>
          );
        })}
      </div>

      {/* Synthèse narrative */}
      <div style={{background:"#F7E6FF",border:"1px solid #F7E6FF",borderRadius:"12px",padding:"16px 24px"}}>
        <div style={{fontWeight:700,color:"#6A009C",fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
          <i className="ph-light ph-article" style={{fontSize:"16px"}}/>Synthèse du rapport
        </div>
        <p style={{margin:"0 0 8px",fontSize:"14px",color:"#6A009C",lineHeight:1.65}}>
          L'enquête sociale menée auprès des <strong>{LOTS.length} lots</strong> de La Résidence Vauban a obtenu un taux de participation de <strong>{Math.round(ok/LOTS.length*100)}%</strong> ({ok} lots répondus). Les résultats révèlent un profil de copropriété majoritairement composé de propriétaires occupants avec une occupation moyenne de <strong>{avgOccupants} personnes par logement</strong> et un RFR moyen déclaré de <strong>{avgRfr.toLocaleString("fr-FR")} €</strong>.
        </p>
        <p style={{margin:"0 0 8px",fontSize:"14px",color:"#6A009C",lineHeight:1.65}}>
          <strong>{soutienData.slice(0,2).reduce((s,d)=>s+d.val,0)} ménages ({Math.round(soutienData.slice(0,2).reduce((s,d)=>s+d.val,0)/totalRep*100)}%)</strong> se déclarent favorables ou favorables avec réserves au projet de rénovation. Les principales réserves portent sur le montant du reste à charge et les nuisances de chantier.{nbDiffFin>0&&<> <strong>{nbDiffFin} ménage{nbDiffFin>1?"s":""}</strong> signal{nbDiffFin>1?"ent":"e"} des difficultés à financer leur quote-part.</>}
        </p>
        <p style={{margin:"0 0 8px",fontSize:"14px",color:"#6A009C",lineHeight:1.65}}>
          Les problèmes constatés les plus fréquents sont <strong>les factures élevées</strong> et <strong>les courants d'air</strong>, cohérents avec le DPE E du bâtiment. L'Éco-PTZ et MaPrimeRénov' individuelle sont les solutions de financement les plus plébiscitées.
        </p>
        {(nbHandicap>0||nbIsolement>0||nbMonoparental>0)&&(
          <p style={{margin:0,fontSize:"14px",color:"#6A009C",lineHeight:1.65}}>
            Sur le plan social, on recense <strong>{nbHandicap} ménage{nbHandicap>1?"s":""} avec une personne en situation de handicap</strong>, <strong>{nbIsolement} en isolement social</strong> et <strong>{nbMonoparental} famille{nbMonoparental>1?"s":""} monoparentale{nbMonoparental>1?"s":""}</strong> nécessitant un accompagnement individualisé.
          </p>
        )}
      </div>
    </div>
  );
}


function EnqueteSociale() {
  const [view,        setView]        = useState<"suivi"|"parametrage">("suivi");
  const [sel,         setSel]         = useState<number|null>(null);
  const [filtre,      setFiltre]      = useState<Q|null>(null);
  const [showRapport, setShowRapport] = useState(false);
  const [lotDetail,   setLotDetail]   = useState<number|null>(null);
  const [showRelance, setShowRelance] = useState(false);
  const [relanceMsg,  setRelanceMsg]  = useState(`Bonjour,\n\nNous vous contactons dans le cadre du projet de rénovation de la Résidence Vauban.\n\nVotre participation à l'enquête sociale est indispensable pour établir votre plan de financement personnalisé (MaPrimeRénov' Copro, Éco-PTZ collectif…).\n\nMerci de bien vouloir compléter le formulaire en cliquant sur le lien ci-dessous avant le 15 août 2025.\n\nL'équipe Marius Rénov' reste disponible pour toute question.\n\nCordialement,\nSebastian Ruiz — AMO Copro · Marius Rénov'`);

  if (view === "parametrage") return <ParametrageEnquete onBack={()=>setView("suivi")} />;


  const ok    = LOTS.filter(l=>l.statut==="répondu").length;
  const taux  = Math.round(ok/LOTS.length*100);

  // Compteurs calculés depuis les mêmes données que le tableau
  const tm = LOTS.filter(l=>l.qual==="très modeste").length;   // 2
  const mo = LOTS.filter(l=>l.qual==="modeste").length;         // 3
  const in_ = LOTS.filter(l=>l.qual==="intermédiaire").length; // 2
  const su = LOTS.filter(l=>l.qual==="supérieur").length;       // 2
  const nq = LOTS.filter(l=>l.qual==="inconnu").length;         // 3

  const kpis = [
    {label:"Très modestes",  val:tm,  qual:"très modeste"  as Q, ...qColor("très modeste")},
    {label:"Modestes",        val:mo,  qual:"modeste"       as Q, ...qColor("modeste")},
    {label:"Intermédiaires",  val:in_, qual:"intermédiaire" as Q, ...qColor("intermédiaire")},
    {label:"Supérieurs",      val:su,  qual:"supérieur"     as Q, ...qColor("supérieur")},
    {label:"Non qualifiés",   val:nq,  qual:"inconnu"       as Q, ...qColor("inconnu")},
  ];

  const lotsAffiches = filtre ? LOTS.filter(l=>l.qual===filtre) : LOTS;

  const toggleFiltre = (q: Q) => {
    setSel(null);
    setFiltre(f => f===q ? null : q);
  };

  return (
    <div style={{padding:"24px 32px"}}>
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:"4px"}}>
        <h4 style={{margin:0,fontWeight:700,color:C.primary,fontSize:"20px",fontFamily:"Montserrat,sans-serif"}}>Enquête Sociale</h4>
        <div style={{display:"flex",gap:"8px"}}>
          <button onClick={()=>setShowRapport(true)} style={{fontFamily:"Montserrat,sans-serif",display:"flex",alignItems:"center",gap:"8px",background:"#7A00B3",border:"none",borderRadius:"4px",padding:"8px 16px",fontSize:"14px",fontWeight:600,color:"#FFFFFF",cursor:"pointer",flexShrink:0}}>
            <i className="ph-light ph-chart-bar" style={{fontSize:"16px"}}/>
            Générer rapport
          </button>
          <button onClick={()=>setShowRelance(true)} style={{fontFamily:"Montserrat,sans-serif",display:"flex",alignItems:"center",gap:"8px",background:"#F57C00",border:"none",borderRadius:"4px",padding:"8px 16px",fontSize:"14px",fontWeight:600,color:"#FFFFFF",cursor:"pointer",flexShrink:0}}>
            <i className="ph-light ph-megaphone" style={{fontSize:"16px"}}/>
            Relance groupée ({LOTS.filter(l=>l.statut==="relancé"||l.statut==="en attente").length})
          </button>
          <button onClick={()=>setView("parametrage")} style={{fontFamily:"Montserrat,sans-serif",display:"flex",alignItems:"center",gap:"8px",background:"#2E596B",border:"none",borderRadius:"4px",padding:"8px 16px",fontSize:"14px",fontWeight:600,color:"#FFFFFF",cursor:"pointer",flexShrink:0}}>
            <i className="ph-light ph-sliders-horizontal" style={{fontSize:"16px"}}/>
            Paramétrer l'enquête
          </button>

          {/* ── Modale Relance groupée ── */}
          {showRelance&&(
            <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.45)",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center"}}>
              <div style={{background:"#FFFFFF",borderRadius:"16px",width:"620px",maxHeight:"85vh",display:"flex",flexDirection:"column",boxShadow:"0 20px 60px rgba(0,0,0,0.22)"}}>
                {/* Header */}
                <div style={{padding:"24px 24px 16px",borderBottom:"1px solid #F2F3F4",display:"flex",alignItems:"center",gap:"12px"}}>
                  <div style={{width:"38px",height:"38px",borderRadius:"8px",background:"#FEF2E6",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                    <i className="ph-light ph-megaphone" style={{fontSize:"20px",color:"#F57C00"}}/>
                  </div>
                  <div>
                    <div style={{fontWeight:700,color:"#13252D",fontSize:"16px"}}>Relance groupée</div>
                    <div style={{fontSize:"12px",color:"#587A89"}}>{LOTS.filter(l=>l.statut==="relancé"||l.statut==="en attente").length} copropriétaires à relancer</div>
                  </div>
                  <button onClick={()=>setShowRelance(false)} style={{marginLeft:"auto",background:"none",border:"none",cursor:"pointer",padding:"8px",borderRadius:"4px",color:"#9FB3BB"}}>
                    <i className="ph-light ph-x" style={{fontSize:"20px"}}/>
                  </button>
                </div>
                {/* Destinataires */}
                <div style={{padding:"16px 24px 0"}}>
                  <div style={{fontSize:"12px",fontWeight:700,color:"#587A89",marginBottom:"8px"}}>Destinataires</div>
                  <div style={{display:"flex",flexWrap:"wrap",gap:"8px",marginBottom:"16px"}}>
                    {LOTS.filter(l=>l.statut==="relancé"||l.statut==="en attente").map(l=>(
                      <span key={l.id} style={{display:"flex",alignItems:"center",gap:"4px",background:l.statut==="relancé"?"#FEF2E6":"#FBEAEA",border:`1px solid ${l.statut==="relancé"?"#FBC996":"#FAC9B4"}`,borderRadius:"4px",padding:"4px 8px",fontSize:"12px",fontWeight:600,color:l.statut==="relancé"?"#F57C00":"#D32F2F"}}>
                        <i className={`ph-light ${l.statut==="relancé"?"ph-clock":"ph-hourglass"}`} style={{fontSize:"12px"}}/>
                        {l.proprietaire} · Lot {l.id}
                      </span>
                    ))}
                  </div>
                  <div style={{fontSize:"12px",fontWeight:700,color:"#587A89",marginBottom:"8px"}}>Message</div>
                  <textarea
                    value={relanceMsg}
                    onChange={e=>setRelanceMsg(e.target.value)}
                    style={{width:"100%",height:"180px",border:"1.5px solid #EAEEF0",borderRadius:"8px",padding:"12px 16px",fontSize:"14px",fontFamily:"Inter,sans-serif",resize:"vertical",outline:"none",color:"#13252D",lineHeight:"1.6",boxSizing:"border-box"}}
                  />
                </div>
                {/* Footer */}
                <div style={{padding:"16px 24px 24px",display:"flex",justifyContent:"flex-end",gap:"12px"}}>
                  <button onClick={()=>setShowRelance(false)} style={{fontFamily:"Montserrat,sans-serif",background:"#F2F3F4",border:"none",cursor:"pointer",padding:"8px 16px",borderRadius:"8px",fontSize:"14px",fontWeight:600,color:"#2A5161"}}>Annuler</button>
                  <button onClick={()=>setShowRelance(false)} style={{fontFamily:"Montserrat,sans-serif",background:"#F57C00",border:"none",cursor:"pointer",padding:"8px 24px",borderRadius:"8px",fontSize:"14px",fontWeight:700,color:"#FFFFFF",display:"flex",alignItems:"center",gap:"8px"}}>
                    <i className="ph-light ph-paper-plane-tilt" style={{fontSize:"16px"}}/>
                    Envoyer à {LOTS.filter(l=>l.statut==="relancé"||l.statut==="en attente").length} copropriétaires
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
      <p style={{margin:"0 0 24px",color:"#587A89",fontSize:"14px"}}>
        Taux de réponse : <strong style={{color:C.primary}}>{taux}%</strong> · {ok} répondus · {LOTS.filter(l=>l.statut==="relancé").length} relancés · {LOTS.filter(l=>l.statut==="en attente").length} en attente
      </p>

      {/* Barre progression */}
      <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px",marginBottom:"16px"}}>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:"8px"}}>
          <span style={{fontSize:"14px",color:"#587A89"}}>Taux de participation</span>
          <span style={{fontSize:"16px",fontWeight:700,color:C.secondary}}>{taux}%</span>
        </div>
        <div style={{height:"8px",background:"#EAEEF0",borderRadius:"999px"}}>
          <div style={{width:`${taux}%`,height:"8px",background:C.secondary,borderRadius:"999px"}}/>
        </div>
      </div>

      {/* KPIs cliquables → filtre tableau */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:"12px",marginBottom:"16px"}}>
        {kpis.map(k=>{
          const actif = filtre===k.qual;
          return (
            <div key={k.label}
              onClick={()=>toggleFiltre(k.qual)}
              title="Cliquer pour filtrer le tableau"
              style={{
                background:k.bg,
                border:`2px solid ${actif ? k.c : k.c+"30"}`,
                borderRadius:"8px",padding:"16px 16px",
                cursor:"pointer",
                transform: actif?"scale(1.02)":"scale(1)",
                transition:"all 0.15s",
                boxShadow: actif?`0 0 0 3px ${k.c}20`:"none",
              }}>
              <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between"}}>
                <div style={{fontSize:"28px",fontWeight:700,color:k.c,lineHeight:1}}>{k.val}</div>
                {actif && (
                  <span style={{fontSize:"10px",background:k.c,color:"#FFFFFF",borderRadius:"999px",padding:"2px 8px",fontWeight:700,marginTop:"2px"}}>filtré</span>
                )}
              </div>
              <div style={{fontSize:"12px",color:"#587A89",marginTop:"4px"}}>{k.label}</div>
              <div style={{fontSize:"10px",color:k.c,marginTop:"4px",opacity:0.8}}>
                {actif ? "▲ cliquer pour tout afficher" : "▼ cliquer pour filtrer"}
              </div>
            </div>
          );
        })}
      </div>

      {/* Tableau */}
      <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",overflow:"hidden"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 16px",borderBottom:"1px solid #F2F3F4"}}>
          <span style={{fontSize:"14px",fontWeight:600,color:C.primary}}>
            {filtre
              ? <><span style={{color:"#9FB3BB",fontWeight:400}}>Filtre : </span>{kpis.find(k=>k.qual===filtre)?.label} · {lotsAffiches.length} lot{lotsAffiches.length>1?"s":""} <button onClick={()=>setFiltre(null)} style={{fontFamily:"Montserrat,sans-serif",fontSize:"12px",color:C.secondary,fontWeight:600,background:"none",border:"none",cursor:"pointer",marginLeft:"8px"}}>✕ tout afficher</button></>
              : <>{LOTS.length} lots</>
            }
          </span>
          <button style={{fontFamily:"Montserrat,sans-serif",fontSize:"12px",color:C.secondary,border:`1px solid ${C.secondary}`,borderRadius:"4px",padding:"4px 12px",background:"transparent",cursor:"pointer",fontWeight:600}}>
            + Relances groupées
          </button>
        </div>
        <table style={{width:"100%",fontSize:"14px",borderCollapse:"collapse"}}>
          <thead>
            <tr style={{background:"#FBFBFB",borderBottom:"1px solid #EAEEF0"}}>
              {["Lot","Occupant","Statut","Qualification","Action"].map((h,i)=>(
                <th key={h} style={{textAlign:i===4?"right":"left",padding:"12px 16px",fontWeight:600,color:"#587A89",fontSize:"12px"}}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {lotsAffiches.map(lot=>{
              const qc=qColor(lot.qual);
              const highlighted = filtre===lot.qual;
              return (
                <tr key={lot.id} onClick={()=>setSel(sel===lot.id?null:lot.id)}
                  style={{
                    borderBottom:"1px solid #F2F3F4",
                    background: sel===lot.id ? "#E6F3FA" : highlighted ? qc.bg+"60" : "transparent",
                    cursor:"pointer",
                    transition:"background 0.1s",
                  }}>
                  <td style={{padding:"12px 16px",fontWeight:600,color:C.primary}}>Lot {lot.id} — {lot.type}</td>
                  <td style={{padding:"12px 16px"}}>
                    <div style={{color:"#213F4C"}}>{lot.nom}</div>
                    <div style={{fontSize:"12px",color:"#9FB3BB"}}>{lot.statut_lot}</div>
                  </td>
                  <td style={{padding:"12px 16px"}}>
                    <span style={{display:"flex",alignItems:"center",gap:"4px",
                      color:lot.statut==="répondu"?C.success:lot.statut==="relancé"?C.warning:"#9FB3BB"}}>
                      {lot.statut==="répondu"?<CheckCircle2 size={14}/>:lot.statut==="relancé"?<Clock size={14}/>:<AlertCircle size={14}/>}
                      {lot.statut}
                    </span>
                  </td>
                  <td style={{padding:"12px 16px"}}>
                    <span style={{fontSize:"12px",padding:"2px 8px",borderRadius:"999px",fontWeight:600,background:qc.bg,color:qc.c}}>{lot.qual}</span>
                  </td>
                  <td style={{padding:"12px 16px",textAlign:"right"}}>
                    {lot.statut!=="répondu"
                      ?<button style={{fontFamily:"Montserrat,sans-serif",fontSize:"12px",color:C.secondary,fontWeight:600,background:"none",border:"none",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:"4px"}}><Send size={12}/>Relancer</button>
                      :<button onClick={e=>{e.stopPropagation();setLotDetail(lot.id);}} style={{fontFamily:"Montserrat,sans-serif",fontSize:"12px",color:C.secondary,background:"#E6F3FA",border:`1px solid ${C.secondary}40`,borderRadius:"4px",padding:"4px 8px",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:"4px",fontWeight:600}}><FileText size={12}/>Voir réponses</button>
                    }
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Modal : Réponses lot sélectionné */}
      {lotDetail!==null&&(()=>{
        const lot=LOTS.find(l=>l.id===lotDetail)!;
        const rep=SURVEY_RESPONSES[lotDetail];
        const qp=Math.round(COPRO.budget*lot.t/COPRO.T);
        const qc=qColor(lot.qual);
        const SOUTIEN_LABEL:{[k:string]:[string,string]}={
          "oui":["Favorable","#388E3C"],"oui_avec_reserve":["Favorable avec réserves","#F7922B"],
          "neutre":["Neutre","#587A89"],"non":["Défavorable","#D32F2F"]};
        const [sl,sc]=rep?(SOUTIEN_LABEL[rep.soutien_renov]||["—","#9FB3BB"]):["—","#9FB3BB"];
        const OuiNon=(v:boolean|undefined)=>v===undefined?"—":v
          ?<span style={{color:"#388E3C",fontWeight:700}}>✓ Oui</span>
          :<span style={{color:"#9FB3BB"}}>Non</span>;
        const SectionTitle=({emoji,title}:{emoji:string;title:string})=>(
          <div style={{display:"flex",alignItems:"center",gap:"8px",borderBottom:"2px solid #F2F3F4",paddingBottom:"8px",marginBottom:"12px",marginTop:"4px"}}>
            <span style={{fontSize:"16px"}}>{emoji}</span>
            <span style={{fontWeight:700,color:C.primary,fontSize:"12px"}}>{title}</span>
          </div>
        );
        return(
          <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.5)",zIndex:600,display:"flex",alignItems:"center",justifyContent:"center",padding:"24px"}}
            onClick={()=>setLotDetail(null)}>
            <div style={{background:"#FFFFFF",borderRadius:"16px",width:"100%",maxWidth:"660px",maxHeight:"90vh",overflow:"auto",boxShadow:"0 24px 64px rgba(0,0,0,0.2)"}}
              onClick={e=>e.stopPropagation()}>
              {/* Header */}
              <div style={{background:`linear-gradient(135deg,${C.primary},${C.secondary})`,padding:"16px 24px",borderRadius:"14px 14px 0 0",display:"flex",alignItems:"center",justifyContent:"space-between",position:"sticky",top:0,zIndex:1}}>
                <div>
                  <div style={{fontSize:"16px",fontWeight:700,color:"#FFFFFF",fontFamily:"Montserrat,sans-serif"}}>Lot {lot.id} — {lot.nom}</div>
                  <div style={{fontSize:"12px",color:"rgba(255,255,255,0.75)",marginTop:"2px"}}>{lot.type} · {lot.t} tantièmes · {lot.statut_lot}</div>
                </div>
                <div style={{display:"flex",alignItems:"center",gap:"8px"}}>
                  <span style={{background:qc.bg,color:qc.c,borderRadius:"999px",padding:"4px 12px",fontSize:"12px",fontWeight:700}}>{lot.qual}</span>
                  <button onClick={()=>setLotDetail(null)} style={{background:"rgba(255,255,255,0.15)",border:"none",color:"#FFFFFF",width:"30px",height:"30px",borderRadius:"50%",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>✕</button>
                </div>
              </div>
              {rep?(
                <div style={{padding:"24px 24px",display:"flex",flexDirection:"column",gap:"16px"}}>

                  {/* ── S1 : Votre lot ── */}
                  <div>
                    <SectionTitle emoji="🏠" title="Votre lot"/>
                    <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"8px"}}>
                      {[
                        {l:"Numéro de lot",   v:`Lot ${lot.id}`},
                        {l:"Étage",           v:lot.type.includes("RDC")?"Rez-de-chaussée":lot.type.includes("1er")?"1er étage":lot.type.includes("2e")?"2e étage":"—"},
                        {l:"Type / pièces",   v:lot.type},
                        {l:"Surface",         v:"—"},
                        {l:"Tantièmes",       v:`${lot.t} / ${COPRO.T}`},
                        {l:"Quote-part est.", v:fmt(qp)},
                      ].map(k=>(
                        <div key={k.l} style={{background:"#FBFBFB",border:"1px solid #EAEEF0",borderRadius:"4px",padding:"8px 12px"}}>
                          <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"4px"}}>{k.l}</div>
                          <div style={{fontSize:"12px",fontWeight:600,color:C.primary}}>{k.v}</div>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* ── S2 : Statut dans le lot ── */}
                  <div>
                    <SectionTitle emoji="👤" title="Statut dans le lot"/>
                    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"8px"}}>
                      <div style={{background:"#FBFBFB",border:"1px solid #EAEEF0",borderRadius:"4px",padding:"12px 12px"}}>
                        <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"4px"}}>Statut d'occupation</div>
                        <div style={{fontSize:"14px",fontWeight:600,color:C.primary}}>{rep.statut_occu}</div>
                      </div>
                      <div style={{background:"#FBFBFB",border:"1px solid #EAEEF0",borderRadius:"4px",padding:"12px 12px"}}>
                        <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"4px"}}>Année d'acquisition</div>
                        <div style={{fontSize:"14px",fontWeight:600,color:C.primary}}>{rep.annee_acq}</div>
                      </div>
                    </div>
                  </div>

                  {/* ── S3 : Situation du foyer ── */}
                  <div>
                    <SectionTitle emoji="🏡" title="Situation du foyer"/>
                    <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"8px",marginBottom:"12px"}}>
                      {[
                        {l:"Personnes dans le foyer", v:String(rep.occupants)},
                        {l:"Dont enfants à charge",   v:String(rep.enfants)},
                        {l:"RFR déclaré",             v:rep.rfr>0?`${rep.rfr.toLocaleString("fr-FR")} €`:"Non renseigné"},
                        {l:"Conditions d'occupation", v:rep.conditions_occupation},
                        {l:"Charges copro impayées",  v:""},
                        {l:"Difficulté financement",  v:""},
                      ].map((k,i)=>i>=4?(
                        <div key={k.l} style={{background:"#FBFBFB",border:"1px solid #EAEEF0",borderRadius:"4px",padding:"8px 12px"}}>
                          <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"4px"}}>{k.l}</div>
                          <div style={{fontSize:"12px",fontWeight:600}}>{i===4?OuiNon(rep.charges_impayees):OuiNon(rep.difficulte_financement)}</div>
                        </div>
                      ):(
                        <div key={k.l} style={{background:"#FBFBFB",border:"1px solid #EAEEF0",borderRadius:"4px",padding:"8px 12px"}}>
                          <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"4px"}}>{k.l}</div>
                          <div style={{fontSize:"12px",fontWeight:600,color:C.primary}}>{k.v}</div>
                        </div>
                      ))}
                    </div>
                    {/* Indicateurs de fragilité */}
                    <div style={{display:"flex",flexWrap:"wrap",gap:"8px",marginBottom:"8px"}}>
                      {[
                        {label:"Handicap",                v:rep.handicap,      c:"#7A00B3",bg:"#F7E6FF"},
                        {label:"Isolement social",        v:rep.isolement,     c:"#F57C00",bg:"#FEF2E6"},
                        {label:"Famille monoparentale",   v:rep.monoparental,  c:"#2E596B",bg:"#E6F3FA"},
                      ].map(ind=>(
                        <span key={ind.label} style={{
                          padding:"4px 12px",borderRadius:"999px",fontSize:"12px",fontWeight:600,
                          background:ind.v?ind.bg:"#FBFBFB",
                          color:ind.v?ind.c:"#9FB3BB",
                          border:`1px solid ${ind.v?ind.c+"40":"#EAEEF0"}`,
                          opacity:ind.v?1:0.6,
                        }}>
                          {ind.v?"✓":"–"} {ind.label}
                        </span>
                      ))}
                    </div>
                    {/* Problèmes d'inconfort */}
                    <div style={{fontSize:"10px",color:"#587A89",fontWeight:700,marginBottom:"8px"}}>Problèmes d'inconfort constatés</div>
                    <div style={{display:"flex",flexWrap:"wrap",gap:"8px"}}>
                      {rep.issues.map(issue=>(
                        <span key={issue} style={{background:"#FEF2E6",color:"#F57C00",border:"1px solid #FBC996",borderRadius:"4px",padding:"4px 12px",fontSize:"12px",fontWeight:600}}>{issue}</span>
                      ))}
                    </div>
                  </div>

                  {/* ── S4 : Position vis-à-vis du projet ── */}
                  <div>
                    <SectionTitle emoji="🏗️" title="Position vis-à-vis du projet"/>
                    <div style={{background:sc+"10",border:`1px solid ${sc}30`,borderRadius:"8px",padding:"12px 16px",marginBottom:"8px"}}>
                      <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"8px"}}>Soutien au projet de rénovation</div>
                      <div style={{display:"flex",alignItems:"center",gap:"8px"}}>
                        <span style={{fontWeight:700,color:sc,fontSize:"14px"}}>{sl}</span>
                      </div>
                      {rep.reserve_detail&&<div style={{fontSize:"12px",color:"#2A5161",marginTop:"8px",fontStyle:"italic"}}>"{rep.reserve_detail}"</div>}
                    </div>
                    <div style={{display:"grid",gridTemplateColumns:"1fr",gap:"0"}}>
                      <div style={{background:"#FBFBFB",border:"1px solid #EAEEF0",borderRadius:"4px",padding:"8px 12px"}}>
                        <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"4px"}}>Connaissance du DPE actuel du bâtiment</div>
                        <div style={{fontSize:"14px",fontWeight:600,color:C.primary,textTransform:"capitalize"}}>{rep.dpe_connaissance==="oui"?"Oui — connaît le DPE":rep.dpe_connaissance==="approximate"?"Approximativement":"Non — ne connaît pas le DPE"}</div>
                      </div>
                    </div>
                  </div>

                  {/* ── S5 : Financement & charges ── */}
                  <div>
                    <SectionTitle emoji="💰" title="Financement & charges"/>
                    <div style={{marginBottom:"8px"}}>
                      <div style={{fontSize:"10px",color:"#587A89",fontWeight:700,marginBottom:"8px"}}>Options de financement souhaitées</div>
                      <div style={{display:"flex",flexWrap:"wrap",gap:"8px"}}>
                        {rep.financement_pref.map(f=>(
                          <span key={f} style={{background:"#E6F3FA",color:"#2E596B",border:"1px solid #C9E0F0",borderRadius:"4px",padding:"4px 12px",fontSize:"12px",fontWeight:600}}>{f}</span>
                        ))}
                      </div>
                    </div>
                    <div style={{background:"#FBFBFB",border:"1px solid #EAEEF0",borderRadius:"4px",padding:"8px 12px"}}>
                      <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"4px"}}>Charges mensuelles actuelles de copropriété</div>
                      <div style={{fontSize:"14px",fontWeight:600,color:C.primary}}>{rep.charges_mois}</div>
                    </div>
                  </div>

                  {/* ── S7 : Commentaire libre ── */}
                  {rep.commentaire&&(
                    <div>
                      <SectionTitle emoji="🤝" title="Accord et signature — Commentaire libre"/>
                      <div style={{background:"#F3F9EC",border:"1px solid #F7EBB7",borderRadius:"8px",padding:"12px 16px"}}>
                        <div style={{fontSize:"14px",color:"#2A5161",lineHeight:"1.55",fontStyle:"italic"}}>"{rep.commentaire}"</div>
                      </div>
                    </div>
                  )}

                </div>
              ):(
                <div style={{padding:"32px",textAlign:"center",color:"#9FB3BB"}}>
                  <i className="ph-light ph-clipboard-text" style={{fontSize:"36px",display:"block",marginBottom:"8px"}}/>
                  Ce lot n'a pas encore répondu à l'enquête
                </div>
              )}
              <div style={{padding:"16px 24px",borderTop:"1px solid #F2F3F4",display:"flex",justifyContent:"flex-end",gap:"8px"}}>
                <button onClick={()=>setLotDetail(null)} style={{fontFamily:"Montserrat,sans-serif",background:C.secondary,color:"#FFFFFF",border:"none",cursor:"pointer",padding:"8px 16px",borderRadius:"8px",fontSize:"14px",fontWeight:700}}>Fermer</button>
              </div>
            </div>
          </div>
        );
      })()}
      {/* Modal : Rapport d'enquête sociale */}
      {showRapport&&(()=>{
        const repLots=LOTS.filter(l=>l.statut==="répondu").map(l=>SURVEY_RESPONSES[l.id]).filter(Boolean);
        const totalRep=repLots.length;
        const soutienData=[
          {label:"Favorables",val:repLots.filter(r=>r.soutien_renov==="oui").length,c:"#388E3C",bg:"#F3F9EC"},
          {label:"Fav. avec réserves",val:repLots.filter(r=>r.soutien_renov==="oui_avec_reserve").length,c:"#F7922B",bg:"#F7EBB7"},
          {label:"Neutres",val:repLots.filter(r=>r.soutien_renov==="neutre").length,c:"#587A89",bg:"#F2F3F4"},
          {label:"Défavorables",val:repLots.filter(r=>r.soutien_renov==="non").length,c:"#D32F2F",bg:"#FBEAEA"},
        ];
        const allIssues=repLots.flatMap(r=>r.issues);
        const issueCount=allIssues.reduce((acc,i)=>{acc[i]=(acc[i]||0)+1;return acc;},{} as Record<string,number>);
        const issuesSorted=Object.entries(issueCount).sort(([,a],[,b])=>b-a);
        const allFin=repLots.flatMap(r=>r.financement_pref);
        const finCount=allFin.reduce((acc,f)=>{acc[f]=(acc[f]||0)+1;return acc;},{} as Record<string,number>);
        const finSorted=Object.entries(finCount).sort(([,a],[,b])=>b-a);
        const avgOccupants=Math.round(repLots.reduce((s,r)=>s+r.occupants,0)/totalRep*10)/10;
        const dpeConnus=repLots.filter(r=>r.dpe_connaissance==="oui").length;
        // Indicateurs de fragilité (S3)
        const nbHandicap=repLots.filter(r=>r.handicap).length;
        const nbIsolement=repLots.filter(r=>r.isolement).length;
        const nbMonoparental=repLots.filter(r=>r.monoparental).length;
        const nbDiffFin=repLots.filter(r=>r.difficulte_financement).length;
        const nbChargesImp=repLots.filter(r=>r.charges_impayees).length;
        const avgRfr=Math.round(repLots.filter(r=>r.rfr>0).reduce((s,r)=>s+r.rfr,0)/repLots.filter(r=>r.rfr>0).length);
        const nbEnfants=repLots.reduce((s,r)=>s+r.enfants,0);
        return(
          <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.55)",zIndex:600,display:"flex",alignItems:"center",justifyContent:"center",padding:"24px"}}
            onClick={()=>setShowRapport(false)}>
            <div style={{background:"#FFFFFF",borderRadius:"16px",width:"100%",maxWidth:"820px",maxHeight:"90vh",overflow:"auto",boxShadow:"0 24px 64px rgba(0,0,0,0.2)"}}
              onClick={e=>e.stopPropagation()}>
              {/* Header rapport */}
              <div style={{background:"linear-gradient(135deg,#7A00B3,#7A00B3)",padding:"24px 24px",borderRadius:"16px 16px 0 0",display:"flex",alignItems:"flex-start",justifyContent:"space-between"}}>
                <div>
                  <div style={{fontSize:"20px",fontWeight:700,color:"#FFFFFF",fontFamily:"Montserrat,sans-serif",marginBottom:"2px"}}>Rapport d'Enquête Sociale</div>
                  <div style={{fontSize:"12px",color:"rgba(255,255,255,0.75)"}}>La Résidence Vauban · Rénov'HdF · {new Date().toLocaleDateString("fr-FR",{day:"numeric",month:"long",year:"numeric"})}</div>
                </div>
                <button onClick={()=>setShowRapport(false)} style={{background:"rgba(255,255,255,0.15)",border:"none",color:"#FFFFFF",width:"32px",height:"32px",borderRadius:"50%",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",fontSize:"16px"}}>✕</button>
              </div>
              <div style={{padding:"24px 24px",display:"flex",flexDirection:"column",gap:"24px"}}>
                {/* KPIs synthèse */}
                <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:"12px"}}>
                  {[
                    {l:"Taux de participation",v:`${Math.round(ok/LOTS.length*100)}%`,sub:`${ok}/${LOTS.length} lots`,c:"#7A00B3",bg:"#F7E6FF",icon:"ph-percent"},
                    {l:"Occupation moyenne",v:`${avgOccupants} pers.`,sub:"par logement",c:"#2E596B",bg:"#E6F3FA",icon:"ph-users"},
                    {l:"DPE connu",v:`${Math.round(dpeConnus/totalRep*100)}%`,sub:"des répondants",c:"#388E3C",bg:"#F3F9EC",icon:"ph-thermometer"},
                    {l:"Favorables",v:`${Math.round(soutienData.slice(0,2).reduce((s,d)=>s+d.val,0)/totalRep*100)}%`,sub:"au projet (dont réserves)",c:"#F7922B",bg:"#F7EBB7",icon:"ph-thumbs-up"},
                  ].map(k=>(
                    <div key={k.l} style={{background:k.bg,border:`1px solid ${k.c}20`,borderRadius:"8px",padding:"12px 16px"}}>
                      <div style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                        <i className={`ph-light ${k.icon}`} style={{fontSize:"14px",color:k.c}}/>
                        <span style={{fontSize:"10px",color:"#587A89",fontWeight:700}}>{k.l}</span>
                      </div>
                      <div style={{fontSize:"24px",fontWeight:700,color:k.c,fontFamily:"Montserrat,sans-serif",lineHeight:1}}>{k.v}</div>
                      <div style={{fontSize:"10px",color:k.c+"99",marginTop:"4px"}}>{k.sub}</div>
                    </div>
                  ))}
                </div>
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"16px"}}>
                  {/* Qualification */}
                  <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
                    <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
                      <i className="ph-light ph-users" style={{fontSize:"16px",color:"#7A00B3"}}/>Qualification des ménages
                    </div>
                    {([["très modeste",tm,"#D32F2F","#FBEAEA"],["modeste",mo,"#F57C00","#FEF2E6"],["intermédiaire",in_,"#2E596B","#E6F3FA"],["supérieur",su,"#388E3C","#F3F9EC"],["inconnu",nq,"#587A89","#F2F3F4"]] as [string,number,string,string][]).map(([label,val,c,bg])=>{
                      const pct=LOTS.length>0?Math.round(val/LOTS.length*100):0;
                      return(
                        <div key={label} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                          <span style={{fontSize:"12px",color:"#2A5161",minWidth:"90px",textTransform:"capitalize"}}>{label}</span>
                          <div style={{flex:1,height:"8px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                            <div style={{width:pct+"%",height:"100%",background:c,borderRadius:"999px"}}/>
                          </div>
                          <span style={{fontSize:"12px",fontWeight:700,color:c,minWidth:"28px",textAlign:"right"}}>{val}</span>
                          <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"28px"}}>{pct}%</span>
                        </div>
                      );
                    })}
                  </div>
                  {/* Soutien projet */}
                  <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
                    <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
                      <i className="ph-light ph-thumbs-up" style={{fontSize:"16px",color:"#7A00B3"}}/>Position vis-à-vis du projet
                    </div>
                    {soutienData.map(s=>{
                      const pct=totalRep>0?Math.round(s.val/totalRep*100):0;
                      return(
                        <div key={s.label} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                          <span style={{fontSize:"12px",color:"#2A5161",minWidth:"115px"}}>{s.label}</span>
                          <div style={{flex:1,height:"8px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                            <div style={{width:pct+"%",height:"100%",background:s.c,borderRadius:"999px"}}/>
                          </div>
                          <span style={{fontSize:"12px",fontWeight:700,color:s.c,minWidth:"20px",textAlign:"right"}}>{s.val}</span>
                          <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"28px"}}>{pct}%</span>
                        </div>
                      );
                    })}
                  </div>
                  {/* Problèmes constatés */}
                  <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
                    <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
                      <i className="ph-light ph-warning-circle" style={{fontSize:"16px",color:"#F57C00"}}/>Problèmes les plus cités
                    </div>
                    {issuesSorted.map(([issue,count])=>{
                      const pct=Math.round(count/totalRep*100);
                      return(
                        <div key={issue} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                          <span style={{fontSize:"12px",color:"#2A5161",minWidth:"130px"}}>{issue}</span>
                          <div style={{flex:1,height:"8px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                            <div style={{width:pct+"%",height:"100%",background:"#F57C00",borderRadius:"999px"}}/>
                          </div>
                          <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"36px",textAlign:"right"}}>{count} lots · {pct}%</span>
                        </div>
                      );
                    })}
                  </div>
                  {/* Financement */}
                  <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
                    <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
                      <i className="ph-light ph-bank" style={{fontSize:"16px",color:"#2E596B"}}/>Financement souhaité
                    </div>
                    {finSorted.map(([fin,count])=>{
                      const pct=Math.round(count/totalRep*100);
                      return(
                        <div key={fin} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                          <span style={{fontSize:"12px",color:"#2A5161",minWidth:"150px",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}} title={fin}>{fin}</span>
                          <div style={{flex:1,height:"8px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                            <div style={{width:pct+"%",height:"100%",background:"#2E596B",borderRadius:"999px"}}/>
                          </div>
                          <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"36px",textAlign:"right"}}>{count} lots</span>
                        </div>
                      );
                    })}
                  </div>
                </div>
                {/* Indicateurs de fragilité sociale (S3) */}
                <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
                  <div style={{fontWeight:700,color:C.primary,fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
                    <i className="ph-light ph-shield-warning" style={{fontSize:"16px",color:"#F57C00"}}/>Indicateurs de fragilité sociale (Section 3)
                  </div>
                  <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"12px",marginBottom:"12px"}}>
                    {[
                      {l:"RFR moyen déclaré",       v:`${avgRfr.toLocaleString("fr-FR")} €`,  c:"#7A00B3",bg:"#F7E6FF",icon:"ph-currency-eur"},
                      {l:"Enfants à charge (total)", v:String(nbEnfants)+" enfants",            c:"#2E596B",bg:"#E6F3FA",icon:"ph-baby"},
                      {l:"Ménages propriétaires",   v:`${repLots.filter(r=>r.statut_occu.startsWith("Propriétaire occupant")).length}/${totalRep}`, c:"#388E3C",bg:"#F3F9EC",icon:"ph-house"},
                    ].map(k=>(
                      <div key={k.l} style={{background:k.bg,border:`1px solid ${k.c}20`,borderRadius:"8px",padding:"12px 12px"}}>
                        <div style={{display:"flex",alignItems:"center",gap:"4px",marginBottom:"4px"}}>
                          <i className={`ph-light ${k.icon}`} style={{fontSize:"14px",color:k.c}}/>
                          <span style={{fontSize:"10px",color:"#587A89",fontWeight:700}}>{k.l}</span>
                        </div>
                        <div style={{fontSize:"16px",fontWeight:700,color:k.c,fontFamily:"Montserrat,sans-serif"}}>{k.v}</div>
                      </div>
                    ))}
                  </div>
                  {[
                    {label:"Handicap déclaré",                  val:nbHandicap,    c:"#7A00B3"},
                    {label:"Isolement social",                   val:nbIsolement,   c:"#F57C00"},
                    {label:"Famille monoparentale",             val:nbMonoparental,c:"#2E596B"},
                    {label:"Difficultés à financer la quote-part",val:nbDiffFin,   c:"#D32F2F"},
                    {label:"Charges copro impayées",             val:nbChargesImp,  c:"#F7922B"},
                  ].map(s=>{
                    const pct=totalRep>0?Math.round(s.val/totalRep*100):0;
                    return(
                      <div key={s.label} style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"8px"}}>
                        <span style={{fontSize:"12px",color:"#2A5161",minWidth:"200px"}}>{s.label}</span>
                        <div style={{flex:1,height:"7px",background:"#F2F3F4",borderRadius:"999px",overflow:"hidden"}}>
                          <div style={{width:pct+"%",height:"100%",background:s.c,borderRadius:"999px"}}/>
                        </div>
                        <span style={{fontSize:"12px",fontWeight:700,color:s.c,minWidth:"22px",textAlign:"right"}}>{s.val}</span>
                        <span style={{fontSize:"10px",color:"#9FB3BB",minWidth:"30px"}}>{pct}%</span>
                      </div>
                    );
                  })}
                </div>

                {/* Synthèse narrative */}
                <div style={{background:"#F7E6FF",border:"1px solid #F7E6FF",borderRadius:"8px",padding:"16px"}}>
                  <div style={{fontWeight:700,color:"#6A009C",fontSize:"14px",marginBottom:"12px",display:"flex",alignItems:"center",gap:"8px"}}>
                    <i className="ph-light ph-article" style={{fontSize:"16px"}}/>Synthèse du rapport
                  </div>
                  <p style={{margin:"0 0 8px",fontSize:"14px",color:"#6A009C",lineHeight:1.65}}>
                    L'enquête sociale menée auprès des <strong>{LOTS.length} lots</strong> de La Résidence Vauban a obtenu un taux de participation de <strong>{Math.round(ok/LOTS.length*100)}%</strong> ({ok} lots répondus). Les résultats révèlent un profil de copropriété majoritairement composé de propriétaires occupants avec une occupation moyenne de <strong>{avgOccupants} personnes par logement</strong> et un RFR moyen déclaré de <strong>{avgRfr.toLocaleString("fr-FR")} €</strong>.
                  </p>
                  <p style={{margin:"0 0 8px",fontSize:"14px",color:"#6A009C",lineHeight:1.65}}>
                    <strong>{soutienData.slice(0,2).reduce((s,d)=>s+d.val,0)} ménages ({Math.round(soutienData.slice(0,2).reduce((s,d)=>s+d.val,0)/totalRep*100)}%)</strong> se déclarent favorables ou favorables avec réserves au projet de rénovation. Les principales réserves portent sur le montant du reste à charge et les nuisances de chantier.{nbDiffFin>0&&<> <strong>{nbDiffFin} ménage{nbDiffFin>1?"s":""}</strong> signal{nbDiffFin>1?"ent":"e"} des difficultés à financer leur quote-part.</>}
                  </p>
                  <p style={{margin:"0 0 8px",fontSize:"14px",color:"#6A009C",lineHeight:1.65}}>
                    Les problèmes constatés les plus fréquents sont <strong>les factures élevées</strong> et <strong>les courants d'air</strong>, cohérents avec le DPE E du bâtiment. L'Éco-PTZ et MaPrimeRénov' individuelle sont les solutions de financement les plus plébiscitées.
                  </p>
                  {(nbHandicap>0||nbIsolement>0||nbMonoparental>0)&&(
                    <p style={{margin:0,fontSize:"14px",color:"#6A009C",lineHeight:1.65}}>
                      Sur le plan social, on recense <strong>{nbHandicap} ménage{nbHandicap>1?"s":""} avec une personne en situation de handicap</strong>, <strong>{nbIsolement} en isolement social</strong> et <strong>{nbMonoparental} famille{nbMonoparental>1?"s":""} monoparentale{nbMonoparental>1?"s":""}</strong> nécessitant un accompagnement individualisé.
                    </p>
                  )}
                </div>
              </div>
              <div style={{padding:"16px 24px",borderTop:"1px solid #F2F3F4",display:"flex",justifyContent:"flex-end",gap:"8px"}}>
                <button onClick={()=>setShowRapport(false)} style={{fontFamily:"Montserrat,sans-serif",background:"#2E596B",color:"#FFFFFF",border:"none",cursor:"pointer",padding:"8px 24px",borderRadius:"8px",fontSize:"14px",fontWeight:700}}>Fermer</button>
              </div>
            </div>
          </div>
        );
      })()}

      {/* Détail synthétique (ancien sel) */}
      {sel!==null&&(()=>{
        const lot=LOTS.find(l=>l.id===sel)!;
        const qp=Math.round(COPRO.budget*lot.t/COPRO.T);
        return (
          <div style={{marginTop:"12px",background:"#E6F3FA",border:`1px solid ${C.secondary}40`,borderRadius:"8px",padding:"16px",cursor:"pointer"}} onClick={()=>lot.statut==="répondu"&&setLotDetail(lot.id)}>
            <div style={{fontWeight:600,color:C.secondary,marginBottom:"12px",fontSize:"14px",display:"flex",alignItems:"center",gap:"8px"}}>
              Lot {lot.id} — {lot.nom} · {lot.type} · {lot.t} tantièmes
              {lot.statut==="répondu"&&<span style={{fontSize:"12px",color:C.secondary,background:"#FFFFFF",border:`1px solid ${C.secondary}40`,borderRadius:"4px",padding:"2px 8px",fontWeight:700,cursor:"pointer"}}>Voir réponses →</span>}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"12px"}}>
              {[["Statut lot",lot.statut_lot],["Qualification",lot.qual],["Quote-part est.",fmt(qp)]].map(([l,v])=>(
                <div key={l as string}>
                  <div style={{fontSize:"12px",color:"#587A89",marginBottom:"4px"}}>{l}</div>
                  <div style={{fontSize:"14px",fontWeight:600,color:C.primary}}>{v}</div>
                </div>
              ))}
            </div>
          </div>
        );
      })()}
    </div>
  );
}

// ─── PLAN DE FINANCEMENT ────────────────────────────────

// Agrégats copro calculés depuis les LOTS — taux alignés sur l'onglet Financement
const mpr        = Math.round(COPRO.budget * 0.55);   // 45% taux de base + 10% bonus sortie passoire
const cee_tot    = Math.round(COPRO.budget * 0.058);  // CEE toutes fiches (ITE + PAC + VMC + calorifugeage)
const pi_tot     = LOTS.filter(l=>l.qual==="très modeste").length*3000 + LOTS.filter(l=>l.qual==="modeste").length*1500;
const mel_aide   = LOTS.length * 1000;                // Prime MEL rénovation performante 1 000 €/lot
const aides_tot  = mpr + cee_tot + pi_tot + mel_aide;
const rc_tot     = COPRO.budget - aides_tot;
const ecoPTZ_dispo  = LOTS.length * 50000;            // Éco-PTZ rénovation globale : 50 000 €/lot
const ecoPTZ_adopte = Math.min(ecoPTZ_dispo, rc_tot);
const apport_min    = Math.max(0, rc_tot - ecoPTZ_adopte);

// Détail par catégorie pour copro
const CATS: {qual:Q; label:string; color:string; bg:string}[] = [
  {qual:"très modeste",  label:"Très modestes",  ...qColor("très modeste")  as any},
  {qual:"modeste",       label:"Modestes",        ...qColor("modeste")       as any},
  {qual:"intermédiaire", label:"Intermédiaires",  ...qColor("intermédiaire") as any},
  {qual:"supérieur",     label:"Supérieurs",      ...qColor("supérieur")     as any},
  {qual:"inconnu",       label:"Non qualifiés",   ...qColor("inconnu")       as any},
];

function PlanCopro() {
  const [tabC, setTabC] = useState<"aides"|"categories">("aides");

  const pct = (v:number) => Math.round(v/COPRO.budget*100);

  // Calcul par catégorie
  const catStats = CATS.map(cat=>{
    const lots = LOTS.filter(l=>l.qual===cat.qual);
    const totalQP  = lots.reduce((a,l)=>a+Math.round(COPRO.budget*l.t/COPRO.T),0);
    const totalA   = lots.reduce((a,l)=>{
      const qp=Math.round(COPRO.budget*l.t/COPRO.T);
      const pi=l.qual==="très modeste"?3000:l.qual==="modeste"?1500:0;
      return a+Math.round(qp*0.55)+Math.round(qp*0.058)+pi+1000;
    },0);
    const totalRC  = totalQP - totalA;
    return { ...cat, n:lots.length, totalQP, totalA, totalRC, txAide: totalQP>0?Math.round(totalA/totalQP*100):0 };
  });

  return (
    <div>
      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:"12px",marginBottom:"24px"}}>
        {[
          {label:"Budget total travaux",  val:fmt(COPRO.budget), sub:`${LOTS.length} lots · DPE ${COPRO.dpe}`, color:C.primary},
          {label:"Total aides mobilisées",val:fmt(aides_tot),    sub:`${pct(aides_tot)}% du budget`,           color:C.success},
          {label:"Reste à charge global", val:fmt(rc_tot),       sub:`${pct(rc_tot)}% à financer`,             color:C.secondary},
          {label:"Éco-PTZ disponible",    val:fmt(ecoPTZ_dispo), sub:`${LOTS.length} lots × 50 000 €`,         color:"#7A00B3"},
        ].map(k=>(
          <div key={k.label} style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
            <div style={{fontSize:"10px",fontWeight:700,color:"#9FB3BB",marginBottom:"8px"}}>{k.label}</div>
            <div style={{fontSize:"24px",fontWeight:700,color:k.color,lineHeight:1}}>{k.val}</div>
            <div style={{fontSize:"12px",color:"#9FB3BB",marginTop:"4px"}}>{k.sub}</div>
          </div>
        ))}
      </div>

      {/* Barre de financement */}
      <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px",marginBottom:"24px"}}>
        <div style={{fontSize:"12px",fontWeight:600,color:"#587A89",marginBottom:"12px"}}>Répartition du financement</div>
        <div style={{height:"28px",borderRadius:"4px",overflow:"hidden",display:"flex",marginBottom:"12px"}}>
          <div style={{width:`${pct(mpr)}%`,background:C.success,display:"flex",alignItems:"center",justifyContent:"center"}}>
            <span style={{fontSize:"10px",color:"#FFFFFF",fontWeight:700,whiteSpace:"nowrap",padding:"0 4px"}}>MPR {pct(mpr)}%</span>
          </div>
          <div style={{width:`${pct(cee_tot)}%`,background:"#587A89",display:"flex",alignItems:"center",justifyContent:"center"}}>
            <span style={{fontSize:"10px",color:"#FFFFFF",fontWeight:700,whiteSpace:"nowrap",padding:"0 4px"}}>CEE {pct(cee_tot)}%</span>
          </div>
          <div style={{width:`${pct(pi_tot)}%`,background:"#F7922B",display:"flex",alignItems:"center",justifyContent:"center"}}>
            <span style={{fontSize:"10px",color:"#FFFFFF",fontWeight:600}}>PI</span>
          </div>
          <div style={{width:`${pct(mel_aide)}%`,background:"#AE00FF",display:"flex",alignItems:"center",justifyContent:"center"}}>
            <span style={{fontSize:"10px",color:"#FFFFFF",fontWeight:600}}>MEL</span>
          </div>
          <div style={{flex:1,background:"#EAEEF0",display:"flex",alignItems:"center",justifyContent:"center"}}>
            <span style={{fontSize:"10px",color:"#587A89",fontWeight:700}}>RC {pct(rc_tot)}%</span>
          </div>
        </div>
        <div style={{display:"flex",gap:"16px",flexWrap:"wrap"}}>
          {[
            {label:"MaPrimeRénov' Copro (55%)",color:C.success,val:fmt(mpr)},
            {label:"CEE",color:"#587A89",val:fmt(cee_tot)},
            {label:"Primes individuelles",color:"#F7922B",val:fmt(pi_tot)},
            {label:"Aide MEL",color:"#AE00FF",val:fmt(mel_aide)},
            {label:"Reste à charge",color:"#9FB3BB",val:fmt(rc_tot)},
          ].map(l=>(
            <div key={l.label} style={{display:"flex",alignItems:"center",gap:"8px",fontSize:"12px",color:"#587A89"}}>
              <div style={{width:"10px",height:"10px",borderRadius:"2px",background:l.color,flexShrink:0}}/>
              {l.label} — <strong style={{color:C.primary}}>{l.val}</strong>
            </div>
          ))}
        </div>
      </div>

      {/* Tabs détail */}
      <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",overflow:"hidden"}}>
        <div style={{display:"flex",borderBottom:"1px solid #EAEEF0",padding:"0 16px"}}>
          {[{id:"aides",label:"Détail des aides"},{id:"categories",label:"Par catégorie de ménage"}].map(t=>(
            <button key={t.id} onClick={()=>setTabC(t.id as any)} style={{fontFamily:"Montserrat,sans-serif",
              padding:"12px 16px 8px",fontSize:"14px",fontWeight:tabC===t.id?600:400,
              color:tabC===t.id?C.secondary:C.primary,background:"none",border:"none",
              borderBottom:`2px solid ${tabC===t.id?C.secondary:"transparent"}`,
              marginBottom:"-2px",cursor:"pointer",
            }}>{t.label}</button>
          ))}
        </div>

        {tabC==="aides" && (
          <table style={{width:"100%",fontSize:"14px",borderCollapse:"collapse"}}>
            <thead>
              <tr style={{background:"#FBFBFB"}}>
                {["Dispositif","Assiette","Taux","Montant"].map((h,i)=>(
                  <th key={h} style={{padding:"12px 16px",textAlign:i>1?"right":"left",fontWeight:600,color:"#587A89",fontSize:"12px",borderBottom:"1px solid #EAEEF0"}}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {[
                {d:"MaPrimeRénov' Copropriétés",a:fmt(COPRO.budget),t:"55% (base 45% + bonus sortie passoire)",v:mpr,c:C.success},
                {d:"Certificats d'Économie d'Énergie",a:fmt(COPRO.budget),t:"5,8% (ITE + PAC + VMC + calorifugeage)",v:cee_tot,c:"#587A89"},
                {d:"Primes individuelles ménages modestes",a:"Par ménage éligible",t:"Forfait",v:pi_tot,c:"#F7922B"},
                {d:"Aide MEL — Prime rénovation performante",a:`${LOTS.length} lots × 1 000 €`,t:"Forfait/lot",v:mel_aide,c:"#AE00FF"},
              ].map((r,i)=>(
                <tr key={i} style={{borderBottom:"1px solid #F2F3F4"}}>
                  <td style={{padding:"12px 16px",color:C.primary,fontWeight:500}}>{r.d}</td>
                  <td style={{padding:"12px 16px",color:"#587A89",fontSize:"12px"}}>{r.a}</td>
                  <td style={{padding:"12px 16px",textAlign:"right",color:"#587A89"}}>{r.t}</td>
                  <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,color:r.c}}>{fmt(r.v)}</td>
                </tr>
              ))}
              <tr style={{background:"#FBFBFB",borderTop:"2px solid #EAEEF0"}}>
                <td colSpan={3} style={{padding:"12px 16px",fontWeight:700,color:C.primary}}>Total aides mobilisées</td>
                <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,fontSize:"16px",color:C.success}}>{fmt(aides_tot)}</td>
              </tr>
              <tr>
                <td colSpan={3} style={{padding:"12px 16px",color:"#587A89"}}>Reste à charge (avant Éco-PTZ)</td>
                <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,color:C.secondary}}>{fmt(rc_tot)}</td>
              </tr>
              <tr style={{background:"#E6F3FA",borderTop:"1px dashed #C9E0F0"}}>
                <td colSpan={3} style={{padding:"12px 16px",color:"#7A00B3",fontWeight:500}}>Éco-PTZ collectif disponible (prêt 0%)</td>
                <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,color:"#7A00B3"}}>jusqu'à {fmt(ecoPTZ_dispo)}</td>
              </tr>
            </tbody>
          </table>
        )}

        {tabC==="categories" && (
          <table style={{width:"100%",fontSize:"14px",borderCollapse:"collapse"}}>
            <thead>
              <tr style={{background:"#FBFBFB"}}>
                {["Catégorie","Lots","Quote-parts","Aides","Taux couv.","Reste à charge"].map((h,i)=>(
                  <th key={h} style={{padding:"12px 16px",textAlign:i>1?"right":"left",fontWeight:600,color:"#587A89",fontSize:"12px",borderBottom:"1px solid #EAEEF0"}}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {catStats.map(cat=>(
                <tr key={cat.qual} style={{borderBottom:"1px solid #F2F3F4"}}>
                  <td style={{padding:"12px 16px"}}>
                    <span style={{fontSize:"12px",padding:"2px 8px",borderRadius:"999px",fontWeight:600,background:cat.bg,color:cat.c}}>{cat.label}</span>
                  </td>
                  <td style={{padding:"12px 16px",color:"#587A89",textAlign:"right",fontWeight:600}}>{cat.n}</td>
                  <td style={{padding:"12px 16px",textAlign:"right",color:C.primary,fontWeight:500}}>{cat.n>0?fmt(cat.totalQP):"—"}</td>
                  <td style={{padding:"12px 16px",textAlign:"right",color:C.success,fontWeight:600}}>{cat.n>0?fmt(cat.totalA):"—"}</td>
                  <td style={{padding:"12px 16px",textAlign:"right"}}>
                    {cat.n>0
                      ? <div style={{display:"flex",alignItems:"center",gap:"8px",justifyContent:"flex-end"}}>
                          <div style={{width:"50px",height:"6px",background:"#EAEEF0",borderRadius:"999px",overflow:"hidden"}}>
                            <div style={{width:`${cat.txAide}%`,height:"6px",background:cat.txAide>50?C.success:"#F7922B",borderRadius:"999px"}}/>
                          </div>
                          <span style={{fontSize:"12px",fontWeight:600,color:C.primary}}>{cat.txAide}%</span>
                        </div>
                      : "—"
                    }
                  </td>
                  <td style={{padding:"12px 16px",textAlign:"right",color:C.secondary,fontWeight:600}}>{cat.n>0?fmt(cat.totalRC):"—"}</td>
                </tr>
              ))}
              <tr style={{background:"#FBFBFB",borderTop:"2px solid #EAEEF0"}}>
                <td style={{padding:"12px 16px",fontWeight:700,color:C.primary}}>Total</td>
                <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,color:C.primary}}>{LOTS.length}</td>
                <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,color:C.primary}}>{fmt(COPRO.budget)}</td>
                <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,color:C.success}}>{fmt(aides_tot)}</td>
                <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,color:C.primary}}>{pct(aides_tot)}%</td>
                <td style={{padding:"12px 16px",textAlign:"right",fontWeight:700,color:C.secondary}}>{fmt(rc_tot)}</td>
              </tr>
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

function PlanFinancement() {
  const [niveau, setNiveau] = useState<"copro"|"individuel">("copro");
  const [ecoptz,setEcoptz]=useState<"oui"|"non"|"info">("oui");
  const [fp,setFp]=useState<"total"|"partiel"|"non">("partiel");
  const [pret,setPret]=useState<"oui"|"non"|"nsp">("non");
  const [lv,setLv]=useState(0);
  const lot=LOTS[lv];
  const qp=Math.round(COPRO.budget*lot.t/COPRO.T);
  const aids=Math.round(qp*0.55),cee=Math.round(qp*0.058);
  const pi=lot.qual==="très modeste"?3000:lot.qual==="modeste"?1500:0;
  const melL=1000;
  const totA=aids+cee+pi+melL, rc=qp-totA;
  const eAmt=ecoptz==="oui"?Math.min(20000,rc):0;
  const fpAmt=fp==="total"?Math.max(0,rc-eAmt):fp==="partiel"?Math.round((rc-eAmt)*0.4):0;
  const mensE=ecoptz==="oui"?Math.round(eAmt/240):0;
  const gain=Math.round(qp*0.56*0.003)-mensE;

  const btn=(active:boolean):React.CSSProperties=>({
    fontSize:"12px",padding:"8px 16px",borderRadius:"4px",cursor:"pointer",fontWeight:active?600:400,
    background:active?C.secondary:"#FFFFFF",color:active?"#FFFFFF":C.primary,
    border:`1px solid ${active?C.secondary:"#BECCD1"}`,transition:"all 0.15s",
  });

  return (
    <div style={{padding:"24px 32px"}}>
      {/* Header + toggle */}
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:"24px"}}>
        <div>
          <h4 style={{margin:"0 0 4px",fontWeight:700,color:C.primary,fontSize:"20px",fontFamily:"Montserrat,sans-serif"}}>Plan de Financement</h4>
          <p style={{margin:0,color:"#587A89",fontSize:"14px"}}>{COPRO.nom} · {COPRO.adresse}</p>
        </div>
        {/* Toggle segmenté */}
        <div style={{display:"flex",background:"#F2F3F4",borderRadius:"8px",padding:"4px",gap:"4px",flexShrink:0}}>
          {[
            {id:"copro",      label:"Copropriété", icon:"ph-buildings"},
            {id:"individuel", label:"Individuel",  icon:"ph-user"},
          ].map(o=>(
            <button key={o.id} onClick={()=>setNiveau(o.id as any)} style={{fontFamily:"Montserrat,sans-serif",
              display:"flex",alignItems:"center",gap:"8px",
              padding:"8px 16px",borderRadius:"4px",fontSize:"14px",
              fontWeight:niveau===o.id?600:400,
              background:niveau===o.id?"#FFFFFF":"transparent",
              color:niveau===o.id?C.primary:"#587A89",
              border:"none",cursor:"pointer",
              boxShadow:niveau===o.id?"0 1px 3px rgba(0,0,0,0.12)":"none",
              transition:"all 0.15s",
            }}>
              <i className={`ph-light ${o.icon}`} style={{fontSize:"16px"}}/>
              {o.label}
            </button>
          ))}
        </div>
      </div>

      {/* Vue Copropriété */}
      {niveau==="copro" && <PlanCopro/>}

      {/* Vue Individuelle */}
      {niveau==="individuel" && (
        <>
          <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px 16px",marginBottom:"16px"}}>
            <div style={{fontSize:"12px",fontWeight:700,color:"#9FB3BB",marginBottom:"12px"}}>Simulation pour</div>
            <div style={{display:"flex",gap:"8px",flexWrap:"wrap"}}>
              {LOTS.map((l,i)=>(
                <button key={l.id} onClick={()=>setLv(i)} style={btn(lv===i)}>Lot {l.id} · {l.nom.split(" ")[1]}</button>
              ))}
            </div>
          </div>

          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"12px",marginBottom:"16px"}}>
            {[
              {label:"Quote-part travaux",val:fmt(qp),sub:`${lot.t} tantièmes/${COPRO.T}`,color:C.primary},
              {label:"Total aides",val:fmt(totA),sub:`${Math.round(totA/qp*100)}% du coût`,color:C.success},
              {label:"Reste à charge",val:fmt(rc),sub:"Avant Éco-PTZ",color:C.secondary},
            ].map(k=>(
              <div key={k.label} style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
                <div style={{fontSize:"12px",fontWeight:700,color:"#9FB3BB",marginBottom:"8px"}}>{k.label}</div>
                <div style={{fontSize:"24px",fontWeight:700,color:k.color}}>{k.val}</div>
                <div style={{fontSize:"12px",color:"#9FB3BB",marginTop:"4px"}}>{k.sub}</div>
              </div>
            ))}
          </div>

          <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px",marginBottom:"16px"}}>
            <div style={{fontSize:"14px",fontWeight:600,color:C.primary,marginBottom:"16px",display:"flex",alignItems:"center",gap:"8px"}}>
              <Banknote size={16} color={C.secondary}/>Vos choix de financement
            </div>
            {[
              {label:"Éco-PTZ collectif (0%)",opts:[["oui","✅ Oui"],["non","❌ Non"],["info","❓ Me rappeler"]] as [string,string][],val:ecoptz,set:setEcoptz as (v:string)=>void},
              {label:"Apport fonds propres",opts:[["total","Intégralement"],["partiel","Partiellement"],["non","Non"]] as [string,string][],val:fp,set:setFp as (v:string)=>void},
              {label:"Prêt complémentaire",opts:[["oui","Oui"],["non","Non"],["nsp","Je ne sais pas"]] as [string,string][],val:pret,set:setPret as (v:string)=>void},
            ].map(row=>(
              <div key={row.label} style={{marginBottom:"12px"}}>
                <div style={{fontSize:"12px",fontWeight:500,color:"#2A5161",marginBottom:"8px"}}>{row.label}</div>
                <div style={{display:"flex",gap:"8px",flexWrap:"wrap"}}>
                  {row.opts.map(([v,lbl])=><button key={v} onClick={()=>row.set(v)} style={btn(row.val===v)}>{lbl}</button>)}
                </div>
              </div>
            ))}
          </div>

          <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:"12px"}}>
            <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
              <div style={{fontSize:"12px",fontWeight:700,color:"#9FB3BB",marginBottom:"12px"}}>Montage financier</div>
              {[
                {l:"Quote-part travaux",v:fmt(qp),c:C.primary},
                {l:"MPR Copro (55%)",v:`- ${fmt(aids)}`,c:C.success},
                {l:"CEE (5,8%)",v:`- ${fmt(cee)}`,c:"#587A89"},
                {l:"Prime individuelle",v:`- ${fmt(pi)}`,c:"#F7922B"},
                {l:"Aide MEL",v:`- ${fmt(melL)}`,c:"#AE00FF"},
                {l:"Reste à charge",v:fmt(rc),c:C.primary},
                ...(ecoptz==="oui"?[{l:"Éco-PTZ (0%)",v:`- ${fmt(eAmt)}`,c:C.secondary}]:[]),
                ...(fp!=="non"?[{l:"Fonds propres",v:`- ${fmt(fpAmt)}`,c:"#587A89"}]:[]),
              ].map((r,i)=>(
                <div key={i} style={{display:"flex",justifyContent:"space-between",borderBottom:"1px solid #FBFBFB",padding:"8px 0",fontSize:"14px"}}>
                  <span style={{color:"#587A89"}}>{r.l}</span>
                  <span style={{fontWeight:600,color:r.c}}>{r.v}</span>
                </div>
              ))}
            </div>
            <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
              <div style={{fontSize:"12px",fontWeight:700,color:"#9FB3BB",marginBottom:"12px"}}>Impact mensuel</div>
              <div style={{background:"#FBFBFB",borderRadius:"8px",padding:"12px",fontSize:"14px"}}>
                {[
                  {l:"Charges chauffage (avant)",v:"180 €/mois",c:"#587A89"},
                  {l:"Charges estimées (après)",v:"70 €/mois",c:C.success},
                  ...(ecoptz==="oui"?[{l:"Mensualité Éco-PTZ",v:`+ ${mensE} €/mois`,c:"#2A5161"}]:[]),
                ].map((r,i)=>(
                  <div key={i} style={{display:"flex",justifyContent:"space-between",marginBottom:"8px"}}>
                    <span style={{color:"#587A89"}}>{r.l}</span><span style={{fontWeight:500,color:r.c}}>{r.v}</span>
                  </div>
                ))}
                <div style={{borderTop:"1px solid #EAEEF0",paddingTop:"8px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <span style={{fontWeight:600,color:C.primary,fontSize:"14px"}}>Gain net mensuel</span>
                  <span style={{fontWeight:700,fontSize:"20px",color:gain>=0?C.success:C.danger}}>{gain>=0?"+":""}{gain} €/mois</span>
                </div>
              </div>
              <div style={{fontSize:"12px",color:"#9FB3BB",marginTop:"12px",display:"flex",gap:"4px",alignItems:"center"}}>
                <Info size={12}/>Projections provisoires — après AG oct. 2026
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

