function HistoriqueTab() {
  const [filtre, setFiltre] = useState<EventType|"all">("all");
  const [expanded, setExpanded] = useState<number[]>([]);
  const [searchQ, setSearchQ]   = useState("");

  const toggle = (id:number) => setExpanded(p => p.includes(id)?p.filter(x=>x!==id):[...p,id]);

  const typeConfig: Record<EventType,{icon:string;color:string;bg:string;label:string}> = {
    document:  {icon:"ph-file-arrow-up",      color:"#2A5161", bg:"#E6F3FA", label:"Document"},
    signature: {icon:"ph-pen-nib",            color:"#388E3C", bg:"#EBF4EC", label:"Signature"},
    email:     {icon:"ph-envelope-simple",    color:"#AC5700", bg:"#F3F9EC", label:"E-mail"},
    note:      {icon:"ph-notepad",            color:"#7A00B3", bg:"#F7E6FF", label:"Note"},
    etape:     {icon:"ph-flag-checkered",     color:C.primary, bg:"#EAEEF0", label:"Étape"},
    enquete:   {icon:"ph-chats-circle",       color:"#587A89", bg:"#EBF4EC", label:"Enquête"},
    systeme:   {icon:"ph-gear-six",           color:"#587A89", bg:"#FBFBFB", label:"Système"},
  };

  const phaseLabel = (p:number) => ["Création AMO","Qualification & Diagnostic","Élaboration projet","Validation copro","Financement","Travaux","Réception","Post-travaux"][p] ?? `Phase ${p}`;

  const filtered = HISTORY
    .filter(e => filtre==="all" || e.type===filtre)
    .filter(e => searchQ==="" || e.title.toLowerCase().includes(searchQ.toLowerCase()) || (e.detail||"").toLowerCase().includes(searchQ.toLowerCase()))
    .sort((a,b)=> {
      const da = new Date(`${a.date.split("/").reverse().join("-")}T${a.time}`);
      const db = new Date(`${b.date.split("/").reverse().join("-")}T${b.time}`);
      return db.getTime() - da.getTime(); // plus récent en premier
    });

  // Grouper par date
  const grouped: Record<string,HistEvent[]> = {};
  filtered.forEach(e => {
    if(!grouped[e.date]) grouped[e.date]=[];
    grouped[e.date].push(e);
  });
  const dates = Object.keys(grouped).sort((a,b)=>{
    const pa=a.split("/").reverse().join("-"), pb=b.split("/").reverse().join("-");
    return pb.localeCompare(pa);
  });

  const counts: Record<EventType,number> = {document:0,signature:0,email:0,note:0,etape:0,enquete:0,systeme:0};
  HISTORY.forEach(e=>counts[e.type]++);

  return (
    <div style={{padding:"24px 32px"}}>
      {/* Header */}
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:"16px"}}>
        <div>
          <h4 style={{margin:"0 0 4px",fontWeight:700,color:C.primary,fontSize:"20px",fontFamily:"Montserrat,sans-serif"}}>Historique</h4>
          <p style={{margin:0,color:"#587A89",fontSize:"14px"}}>{HISTORY.length} événements · du 08/01/2025 au 04/04/2025</p>
        </div>
      </div>

      {/* Filtres + recherche */}
      <div style={{display:"flex",gap:"12px",marginBottom:"24px",alignItems:"center",flexWrap:"wrap"}}>
        <div style={{position:"relative",flex:"1",minWidth:"180px"}}>
          <i className="ph-light ph-magnifying-glass" style={{position:"absolute",left:"10px",top:"50%",transform:"translateY(-50%)",fontSize:"16px",color:"#9FB3BB"}}/>
          <input value={searchQ} onChange={e=>setSearchQ(e.target.value)} placeholder="Rechercher dans l'historique…"
            style={{width:"100%",paddingLeft:"32px",paddingRight:"12px",height:"34px",border:"1px solid #EAEEF0",borderRadius:"4px",fontSize:"14px",color:C.primary,outline:"none",boxSizing:"border-box"}}/>
        </div>
        <div style={{display:"flex",gap:"8px",flexWrap:"wrap"}}>
          <button onClick={()=>setFiltre("all")} style={{fontFamily:"Montserrat,sans-serif",fontSize:"12px",padding:"4px 12px",borderRadius:"999px",cursor:"pointer",fontWeight:filtre==="all"?600:400,background:filtre==="all"?C.primary:"#FFFFFF",color:filtre==="all"?"#FFFFFF":C.primary,border:`1px solid ${filtre==="all"?C.primary:"#EAEEF0"}`}}>
            Tout ({HISTORY.length})
          </button>
          {(Object.entries(typeConfig) as [EventType,typeof typeConfig[EventType]][]).map(([k,v])=>counts[k]>0&&(
            <button key={k} onClick={()=>setFiltre(f=>f===k?"all":k)} style={{fontFamily:"Montserrat,sans-serif",fontSize:"12px",padding:"4px 12px",borderRadius:"999px",cursor:"pointer",fontWeight:filtre===k?600:400,background:filtre===k?v.bg:"#FFFFFF",color:filtre===k?v.color:C.primary,border:`1px solid ${filtre===k?v.color+"60":"#EAEEF0"}`,display:"flex",alignItems:"center",gap:"4px"}}>
              <i className={`ph-light ${v.icon}`}/>{v.label} ({counts[k]})
            </button>
          ))}
        </div>
      </div>

      {/* Timeline */}
      <div style={{position:"relative"}}>
        {dates.map(date=>(
          <div key={date}>
            {/* Séparateur de date */}
            <div style={{display:"flex",alignItems:"center",gap:"12px",marginBottom:"12px",marginTop:"4px"}}>
              <div style={{height:"1px",flex:1,background:"#EAEEF0"}}/>
              <span style={{fontSize:"12px",fontWeight:700,color:"#9FB3BB",whiteSpace:"nowrap"}}>
                {(()=>{
                  const [d,m,y]=date.split("/");
                  return new Date(`${y}-${m}-${d}`).toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long",year:"numeric"});
                })()}
              </span>
              <div style={{height:"1px",flex:1,background:"#EAEEF0"}}/>
            </div>

            <div style={{display:"flex",flexDirection:"column",gap:"8px",marginBottom:"16px"}}>
              {grouped[date].map(ev=>{
                const tc = typeConfig[ev.type];
                const isOpen = expanded.includes(ev.id);
                const hasDetail = !!ev.detail;
                return (
                  <div key={ev.id} style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",overflow:"hidden",transition:"box-shadow 0.15s"}}
                    onMouseEnter={e=>(e.currentTarget as HTMLElement).style.boxShadow="0 2px 8px rgba(0,0,0,0.06)"}
                    onMouseLeave={e=>(e.currentTarget as HTMLElement).style.boxShadow="none"}>
                    <div onClick={()=>hasDetail&&toggle(ev.id)}
                      style={{display:"flex",alignItems:"flex-start",gap:"12px",padding:"12px 16px",cursor:hasDetail?"pointer":"default"}}>
                      {/* Icône type */}
                      <div style={{width:"32px",height:"32px",borderRadius:"8px",background:tc.bg,flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",marginTop:"2px"}}>
                        <i className={`ph-light ${tc.icon}`} style={{fontSize:"16px",color:tc.color}}/>
                      </div>
                      {/* Contenu */}
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:"8px"}}>
                          <div>
                            <div style={{fontWeight:500,color:C.primary,fontSize:"14px",lineHeight:1.4}}>{ev.title}</div>
                            <div style={{display:"flex",alignItems:"center",gap:"8px",marginTop:"4px",flexWrap:"wrap"}}>
                              <span style={{fontSize:"12px",padding:"2px 8px",borderRadius:"999px",background:tc.bg,color:tc.color,fontWeight:500}}>{tc.label}</span>
                              <span style={{fontSize:"12px",color:"#9FB3BB",display:"flex",alignItems:"center",gap:"4px"}}>
                                <i className="ph-light ph-user-circle" style={{fontSize:"12px"}}/>
                                {ev.actor}
                              </span>
                              <span style={{fontSize:"12px",color:"#9FB3BB",display:"flex",alignItems:"center",gap:"4px"}}>
                                <i className="ph-light ph-tag" style={{fontSize:"12px"}}/>
                                Phase {ev.phase}
                              </span>
                            </div>
                          </div>
                          <div style={{display:"flex",alignItems:"center",gap:"8px",flexShrink:0}}>
                            <span style={{fontSize:"12px",fontWeight:500,color:"#587A89",whiteSpace:"nowrap"}}>{ev.time}</span>
                            {hasDetail && (
                              <i className={`ph-light ${isOpen?"ph-caret-up":"ph-caret-down"}`} style={{fontSize:"14px",color:"#9FB3BB"}}/>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* Détail développé */}
                    {isOpen && ev.detail && (
                      <div style={{borderTop:"1px solid #F2F3F4",padding:"16px 16px 16px 64px",background:"#FBFBFB"}}>
                        <pre style={{margin:0,fontFamily:"Inter,sans-serif",fontSize:"12px",color:"#213F4C",whiteSpace:"pre-wrap",lineHeight:1.7}}>{ev.detail}</pre>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {filtered.length===0 && (
          <div style={{textAlign:"center",padding:"48px 0",color:"#9FB3BB"}}>
            <i className="ph-light ph-magnifying-glass" style={{fontSize:"36px",display:"block",margin:"0 auto 12px"}}/>
            <div style={{fontSize:"14px"}}>Aucun événement trouvé</div>
          </div>
        )}
      </div>
    </div>
  );
}

