function SignaturesTab() {
  const [openDocs, setOpenDocs] = useState<number[]>([3]);
  const [emails, setEmails]     = useState<Record<string,string>>({});
  const [sent, setSent]         = useState<Record<string,boolean>>({});
  const [toast, setToast]       = useState<string|null>(null);

  const toggle = (id:number) => setOpenDocs(p => p.includes(id)?p.filter(x=>x!==id):[...p,id]);

  const handleRelance = (sigKey:string, name:string) => {
    setSent(p=>({...p,[sigKey]:true}));
    setToast(`Relance envoyée à ${name}`);
    setTimeout(()=>setToast(null),2500);
  };

  const statusStyle = (s:SignDoc["status"]) =>
    s==="complété" ? {bg:"#EBF4EC",c:"#388E3C",icon:"ph-check-circle",l:"Complété"} :
    s==="en cours" ? {bg:"#F3F9EC",c:"#AC5700",icon:"ph-hourglass-medium",l:"En cours"} :
                     {bg:"#FBEAEA",c:"#DA5252",icon:"ph-x-circle",l:"Refusé"};

  const totalSignés   = SIGN_DOCS.reduce((a,d)=>a+d.signataires.filter(s=>s.signedAt).length,0);
  const totalAttendus = SIGN_DOCS.reduce((a,d)=>a+d.signataires.length,0);
  const enCours       = SIGN_DOCS.filter(d=>d.status==="en cours").length;

  return (
    <div style={{padding:"24px 32px",position:"relative"}}>
      {/* Toast */}
      {toast && (
        <div style={{position:"fixed",bottom:"28px",right:"28px",zIndex:2000,background:C.primary,color:"#FFFFFF",padding:"12px 24px",borderRadius:"8px",fontSize:"14px",fontWeight:500,boxShadow:"0 4px 16px rgba(0,0,0,0.2)",display:"flex",alignItems:"center",gap:"8px"}}>
          <i className="ph-light ph-paper-plane-tilt" style={{fontSize:"16px",color:"#9DCC66"}}/>
          {toast}
        </div>
      )}

      {/* Header */}
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:"24px"}}>
        <div>
          <h4 style={{margin:"0 0 4px",fontWeight:700,color:C.primary,fontSize:"20px",fontFamily:"Montserrat,sans-serif"}}>Signatures électroniques</h4>
          <p style={{margin:0,color:"#587A89",fontSize:"14px"}}>{totalSignés}/{totalAttendus} signatures recueillies · {enCours} procédure{enCours>1?"s":""} en cours</p>
        </div>
        <button style={{fontFamily:"Montserrat,sans-serif",display:"flex",alignItems:"center",gap:"8px",background:"#2E596B",border:"none",borderRadius:"4px",padding:"8px 16px",fontSize:"14px",fontWeight:600,color:"#FFFFFF",cursor:"pointer"}}>
          <i className="ph-light ph-plus" style={{fontSize:"16px"}}/>
          Nouvelle procédure
        </button>
      </div>

      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"12px",marginBottom:"24px"}}>
        {[
          {label:"Procédures terminées", val:SIGN_DOCS.filter(d=>d.status==="complété").length, icon:"ph-check-circle",  c:C.success,  bg:"#EBF4EC"},
          {label:"En cours de signature",val:enCours,                                            icon:"ph-hourglass-medium",c:"#AC5700",bg:"#F3F9EC"},
          {label:"Signatures recueillies",val:`${totalSignés}/${totalAttendus}`,                 icon:"ph-pen-nib",        c:C.secondary,bg:"#EAEEF0"},
        ].map(k=>(
          <div key={k.label} style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px 16px",display:"flex",alignItems:"center",gap:"12px"}}>
            <div style={{width:"36px",height:"36px",borderRadius:"8px",background:k.bg,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
              <i className={`ph-light ${k.icon}`} style={{fontSize:"20px",color:k.c}}/>
            </div>
            <div>
              <div style={{fontSize:"20px",fontWeight:700,color:C.primary,lineHeight:1}}>{k.val}</div>
              <div style={{fontSize:"12px",color:"#587A89",marginTop:"4px"}}>{k.label}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Liste procédures */}
      <div style={{display:"flex",flexDirection:"column",gap:"12px"}}>
        {SIGN_DOCS.map(doc=>{
          const open = openDocs.includes(doc.id);
          const ss   = statusStyle(doc.status);
          const nbSignés   = doc.signataires.filter(s=>s.signedAt).length;
          const nbTotal    = doc.signataires.length;
          const pct        = Math.round(nbSignés/nbTotal*100);
          return (
            <div key={doc.id} style={{background:"#FFFFFF",border:`1px solid ${doc.status==="en cours"?"#F9B36B":"#EAEEF0"}`,borderRadius:"8px",overflow:"hidden"}}>
              {/* Header procédure */}
              <div onClick={()=>toggle(doc.id)} style={{padding:"16px 16px",cursor:"pointer",userSelect:"none",background:doc.status==="en cours"?"#FBFBFB":"#FBFBFB"}}>
                <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:"12px"}}>
                  <div style={{display:"flex",alignItems:"flex-start",gap:"12px",flex:1}}>
                    <div style={{width:"34px",height:"34px",borderRadius:"8px",background:ss.bg,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,marginTop:"2px"}}>
                      <i className={`ph-light ${ss.icon}`} style={{fontSize:"16px",color:ss.c}}/>
                    </div>
                    <div style={{flex:1}}>
                      <div style={{display:"flex",alignItems:"center",gap:"8px",flexWrap:"wrap",marginBottom:"4px"}}>
                        <span style={{fontWeight:600,color:C.primary,fontSize:"14px"}}>{doc.title}</span>
                        <span style={{fontSize:"10px",fontWeight:600,padding:"2px 8px",borderRadius:"999px",background:ss.bg,color:ss.c}}>{ss.l}</span>
                      </div>
                      <div style={{fontSize:"12px",color:"#587A89",display:"flex",gap:"12px",flexWrap:"wrap"}}>
                        <span><i className="ph-light ph-calendar" style={{marginRight:"4px"}}/>Créée le {doc.createdAt}</span>
                        <span><i className="ph-light ph-files" style={{marginRight:"4px"}}/>{doc.docs.join(", ")}</span>
                      </div>
                      {/* Barre progression signatures */}
                      <div style={{marginTop:"8px",display:"flex",alignItems:"center",gap:"8px"}}>
                        <div style={{flex:1,height:"5px",background:"#EAEEF0",borderRadius:"999px",overflow:"hidden"}}>
                          <div style={{width:`${pct}%`,height:"5px",background:pct===100?C.success:"#F7922B",borderRadius:"999px",transition:"width 0.3s"}}/>
                        </div>
                        <span style={{fontSize:"12px",fontWeight:600,color:pct===100?C.success:"#AC5700",whiteSpace:"nowrap"}}>{nbSignés}/{nbTotal} signatures</span>
                      </div>
                    </div>
                  </div>
                  <i className={`ph-light ${open?"ph-caret-up":"ph-caret-down"}`} style={{fontSize:"14px",color:"#9FB3BB",flexShrink:0,marginTop:"4px"}}/>
                </div>
              </div>

              {/* Signataires */}
              {open && (
                <div style={{borderTop:"1px solid #F2F3F4"}}>
                  <div style={{padding:"12px 16px 8px",fontSize:"12px",fontWeight:700,color:"#9FB3BB"}}>
                    Signataires
                  </div>
                  {doc.signataires.map((sig,si)=>{
                    const sigKey = `${doc.id}-${si}`;
                    const isSigned  = !!sig.signedAt;
                    const isRelancé = sent[sigKey];
                    const emailVal  = emails[sigKey] ?? sig.email;
                    return (
                      <div key={si} style={{display:"flex",alignItems:"center",gap:"12px",padding:"12px 16px",borderTop:"1px solid #FBFBFB",flexWrap:"wrap"}}>
                        {/* Statut icône */}
                        <div style={{width:"28px",height:"28px",borderRadius:"50%",background:isSigned?"#EBF4EC":"#FEF2E6",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                          <i className={`ph-light ${isSigned?"ph-check":"ph-clock"}`} style={{fontSize:"14px",color:isSigned?C.success:"#F7922B"}}/>
                        </div>
                        {/* Infos signataire */}
                        <div style={{flex:1,minWidth:"180px"}}>
                          <div style={{fontWeight:500,color:C.primary,fontSize:"14px"}}>{sig.name}</div>
                          <div style={{fontSize:"12px",color:"#9FB3BB",marginTop:"2px"}}>{sig.role}</div>
                        </div>
                        {/* Email + date ou relance */}
                        {isSigned ? (
                          <div style={{textAlign:"right",minWidth:"180px"}}>
                            <div style={{fontSize:"12px",color:"#587A89",display:"flex",alignItems:"center",gap:"4px",justifyContent:"flex-end"}}>
                              <i className="ph-light ph-envelope" style={{fontSize:"12px"}}/>
                              {sig.email}
                            </div>
                            <div style={{fontSize:"12px",color:C.success,marginTop:"2px",display:"flex",alignItems:"center",gap:"4px",justifyContent:"flex-end"}}>
                              <i className="ph-light ph-check-circle" style={{fontSize:"12px"}}/>
                              Signé le {sig.signedAt}
                            </div>
                          </div>
                        ) : (
                          <div style={{display:"flex",alignItems:"center",gap:"8px",flexWrap:"wrap",flex:"0 0 auto"}}>
                            {isRelancé ? (
                              <span style={{fontSize:"12px",color:C.success,fontWeight:600,display:"flex",alignItems:"center",gap:"4px"}}>
                                <i className="ph-light ph-check-circle"/>Relance envoyée
                              </span>
                            ) : (
                              <>
                                <input
                                  type="email"
                                  placeholder="Email du signataire"
                                  value={emailVal}
                                  onChange={e=>setEmails(p=>({...p,[sigKey]:e.target.value}))}
                                  style={{
                                    height:"32px",border:"1px solid #EAEEF0",borderRadius:"4px",
                                    padding:"0 12px",fontSize:"12px",color:C.primary,
                                    outline:"none",width:"200px",
                                    background: emailVal ? "#FFFFFF" : "#F3F9EC",
                                    borderColor: emailVal ? "#EAEEF0" : "#F9B36B",
                                  }}
                                />
                                <button
                                  onClick={()=>emailVal&&handleRelance(sigKey,sig.name)}
                                  disabled={!emailVal}
                                  style={{fontFamily:"Montserrat,sans-serif",
                                    display:"flex",alignItems:"center",gap:"4px",
                                    height:"32px",padding:"0 12px",borderRadius:"4px",fontSize:"12px",fontWeight:600,
                                    background:emailVal?C.secondary:"#F2F3F4",
                                    color:emailVal?"#FFFFFF":"#BECCD1",
                                    border:"none",cursor:emailVal?"pointer":"not-allowed",
                                    transition:"all 0.15s",
                                  }}>
                                  <i className="ph-light ph-paper-plane-tilt" style={{fontSize:"14px"}}/>
                                  Relancer
                                </button>
                              </>
                            )}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── INTERVENANTS ────────────────────────────────────────
function ActorCard({ icon, name, role, sub, phone, email, badge, badgeColor }: {
  icon:string; name:string; role:string; sub?:string;
  phone?:string; email?:string; badge?:string; badgeColor?:string;
}) {
  return (
    <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px",display:"flex",gap:"16px",alignItems:"flex-start"}}>
      <div style={{width:"40px",height:"40px",borderRadius:"8px",background:"#EAEEF0",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
        <i className={`ph-light ${icon}`} style={{fontSize:"20px",color:C.primary}}/>
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{display:"flex",alignItems:"center",gap:"8px",flexWrap:"wrap",marginBottom:"2px"}}>
          <span style={{fontWeight:600,color:C.primary,fontSize:"14px"}}>{name}</span>
          {badge && <span style={{fontSize:"10px",fontWeight:600,padding:"2px 8px",borderRadius:"999px",background:(badgeColor||C.secondary)+"18",color:badgeColor||C.secondary}}>{badge}</span>}
        </div>
        <div style={{fontSize:"12px",color:C.secondary,fontWeight:500,marginBottom:sub||phone||email?"6px":"0"}}>{role}</div>
        {sub   && <div style={{fontSize:"12px",color:"#587A89",marginBottom:"4px"}}>{sub}</div>}
        <div style={{display:"flex",gap:"12px",flexWrap:"wrap"}}>
          {phone && <a href={`tel:${phone}`} style={{fontSize:"12px",color:"#587A89",textDecoration:"none",display:"flex",alignItems:"center",gap:"4px"}}><i className="ph-light ph-phone" style={{fontSize:"14px",color:"#9FB3BB"}}/>{phone}</a>}
          {email && <a href={`mailto:${email}`} style={{fontSize:"12px",color:C.link,textDecoration:"none",display:"flex",alignItems:"center",gap:"4px"}}><i className="ph-light ph-envelope" style={{fontSize:"14px",color:"#9FB3BB"}}/>{email}</a>}
        </div>
      </div>
    </div>
  );
}

