function MessagerieTab(){
  const [convs, setConvs] = useState<Conv[]>(CONVERSATIONS_INIT);
  const [selId, setSelId] = useState<string>("lecomte");
  const [draft, setDraft] = useState("");
  const [filter, setFilter] = useState<"all"|"unread"|"sent">("all");

  const sel = convs.find(c=>c.id===selId)!;
  const totalUnread = convs.reduce((a,c)=>a+c.unread,0);

  const TAG_COLORS:{[k:string]:string}={
    syndic:"#2E596B",cs:"#225725",copro:"#954C00",expert:"#811D1D",partenaire:"#7A00B3"
  };
  const TAG_LABELS:{[k:string]:string}={
    syndic:"Syndic",cs:"Conseil Syndical",copro:"Copropriétaire",expert:"Expert",partenaire:"Partenaire"
  };

  const sendMsg = ()=>{
    if(!draft.trim()) return;
    const now = new Date();
    const label = `Auj. · ${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;
    setConvs(prev=>prev.map(c=>c.id===selId?{
      ...c,
      messages:[...c.messages,{id:Date.now(),from:"me",text:draft.trim(),time:label,read:true}]
    }:c));
    setDraft("");
  };

  const markRead = (id:string)=>{
    setConvs(prev=>prev.map(c=>c.id===id?{
      ...c,unread:0,messages:c.messages.map(m=>({...m,read:true}))
    }:c));
    setSelId(id);
  };

  const filtered = convs.filter(c=>{
    if(filter==="unread") return c.unread>0;
    if(filter==="sent")   return c.messages.some(m=>m.from==="me");
    return true;
  });

  return (
    <div style={{display:"flex",height:"100%",background:"#FBFBFB"}}>

      {/* ── Colonne gauche : liste conversations ── */}
      <div style={{width:"320px",flexShrink:0,borderRight:"1px solid #EAEEF0",display:"flex",flexDirection:"column",background:"#FFFFFF"}}>

        {/* Header liste */}
        <div style={{padding:"16px 16px 12px",borderBottom:"1px solid #F2F3F4"}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:"12px"}}>
            <div style={{display:"flex",alignItems:"center",gap:"8px"}}>
              <i className="ph-light ph-chats-circle" style={{fontSize:"20px",color:C.secondary}}/>
              <span style={{fontWeight:700,fontSize:"16px",color:C.primary,fontFamily:"Montserrat,sans-serif"}}>Messagerie</span>
              {totalUnread>0&&<span style={{background:C.secondary,color:"#FFFFFF",borderRadius:"999px",fontSize:"12px",fontWeight:700,padding:"2px 8px"}}>{totalUnread}</span>}
            </div>
            <button style={{fontFamily:"Montserrat,sans-serif",background:"#2E596B",border:"none",borderRadius:"4px",padding:"8px 12px",fontSize:"12px",fontWeight:600,color:"#FFFFFF",cursor:"pointer",display:"flex",alignItems:"center",gap:"4px"}}>
              <i className="ph-light ph-pencil-simple" style={{fontSize:"14px"}}/>Nouveau
            </button>
          </div>
          {/* Barre de recherche */}
          <div style={{position:"relative"}}>
            <i className="ph-light ph-magnifying-glass" style={{position:"absolute",left:"10px",top:"50%",transform:"translateY(-50%)",fontSize:"14px",color:"#9FB3BB"}}/>
            <input placeholder="Rechercher un message ou un contact…" style={{width:"100%",padding:"8px 12px 8px 32px",border:"1px solid #EAEEF0",borderRadius:"8px",fontSize:"12px",color:C.primary,outline:"none",boxSizing:"border-box",background:"#FBFBFB"}}/>
          </div>
          {/* Filtres */}
          <div style={{display:"flex",gap:"8px",marginTop:"12px"}}>
            {(["all","unread","sent"] as const).map(f=>(
              <button key={f} onClick={()=>setFilter(f)} style={{fontFamily:"Montserrat,sans-serif",
                flex:1,padding:"4px 0",borderRadius:"4px",border:"1px solid",fontSize:"12px",fontWeight:600,cursor:"pointer",transition:"all 0.15s",
                background:filter===f?C.secondary:"transparent",
                color:filter===f?"#FFFFFF":"#587A89",
                borderColor:filter===f?C.secondary:"#EAEEF0"
              }}>
                {f==="all"?"Tous":f==="unread"?"Non lus":"Envoyés"}
              </button>
            ))}
          </div>
        </div>

        {/* Liste */}
        <div style={{overflowY:"auto",flex:1}}>
          {filtered.map(c=>{
            const last=c.messages[c.messages.length-1];
            const isActive=c.id===selId;
            return (
              <div key={c.id} onClick={()=>markRead(c.id)} style={{
                padding:"12px 16px",cursor:"pointer",borderBottom:"1px solid #FBFBFB",
                background:isActive?"#E6F3FA":c.unread>0?"#FBFBFB":"#FFFFFF",
                borderLeft:isActive?`3px solid ${C.secondary}`:"3px solid transparent",
                transition:"all 0.15s",
              }}
              onMouseEnter={e=>{if(!isActive)(e.currentTarget as HTMLElement).style.background=c.unread>0?"#E6F3FA":"#FBFBFB"}}
              onMouseLeave={e=>{if(!isActive)(e.currentTarget as HTMLElement).style.background=c.unread>0?"#FBFBFB":"#FFFFFF"}}
              >
                <div style={{display:"flex",gap:"12px",alignItems:"flex-start"}}>
                  {/* Avatar */}
                  <div style={{width:"40px",height:"40px",borderRadius:"50%",background:c.couleur,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,fontSize:"14px",fontWeight:700,color:"#FFFFFF",fontFamily:"Montserrat,sans-serif"}}>
                    {c.initiales}
                  </div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:"2px"}}>
                      <span style={{fontWeight:c.unread>0?700:600,fontSize:"14px",color:C.primary,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:"160px"}}>{c.nom}</span>
                      <div style={{display:"flex",alignItems:"center",gap:"4px",flexShrink:0}}>
                        <span style={{fontSize:"10px",color:"#9FB3BB",whiteSpace:"nowrap"}}>{last.time.split("·")[0].trim()}</span>
                        {c.unread>0&&<span style={{background:C.secondary,color:"#FFFFFF",borderRadius:"999px",fontSize:"10px",fontWeight:700,padding:"2px 8px",minWidth:"16px",textAlign:"center"}}>{c.unread}</span>}
                      </div>
                    </div>
                    <div style={{fontSize:"12px",color:"#587A89",marginBottom:"4px",display:"flex",alignItems:"center",gap:"4px"}}>
                      <span style={{background:TAG_COLORS[c.tag]+"18",color:TAG_COLORS[c.tag],borderRadius:"4px",padding:"2px 4px",fontSize:"10px",fontWeight:600}}>{TAG_LABELS[c.tag]}</span>
                    </div>
                    <div style={{fontSize:"12px",color:c.unread>0?"#213F4C":"#9FB3BB",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",fontWeight:c.unread>0?500:400}}>
                      {last.from==="me"&&<span style={{color:"#587A89"}}>Vous : </span>}
                      {last.text}
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* ── Panneau droit : fil de conversation ── */}
      <div style={{flex:1,display:"flex",flexDirection:"column",minWidth:0}}>

        {/* Header conversation */}
        <div style={{padding:"16px 24px",borderBottom:"1px solid #EAEEF0",background:"#FFFFFF",display:"flex",alignItems:"center",justifyContent:"space-between",flexShrink:0}}>
          <div style={{display:"flex",alignItems:"center",gap:"12px"}}>
            <div style={{width:"44px",height:"44px",borderRadius:"50%",background:sel.couleur,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"16px",fontWeight:700,color:"#FFFFFF",fontFamily:"Montserrat,sans-serif"}}>
              {sel.initiales}
            </div>
            <div>
              <div style={{fontWeight:700,fontSize:"14px",color:C.primary,fontFamily:"Montserrat,sans-serif"}}>{sel.nom}</div>
              <div style={{fontSize:"12px",color:"#587A89"}}>{sel.role}</div>
            </div>
          </div>
          <div style={{display:"flex",gap:"8px"}}>
            {[
              {icon:"ph-phone",label:"Appeler"},
              {icon:"ph-video-camera",label:"Visio"},
              {icon:"ph-paperclip",label:"Fichiers"},
              {icon:"ph-dots-three-vertical",label:"Plus"},
            ].map(a=>(
              <button key={a.icon} title={a.label} style={{width:"34px",height:"34px",borderRadius:"8px",border:"1px solid #EAEEF0",background:"#FBFBFB",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:"#587A89",transition:"all 0.15s"}}
                onMouseEnter={e=>(e.currentTarget as HTMLElement).style.background="#EAEEF0"}
                onMouseLeave={e=>(e.currentTarget as HTMLElement).style.background="#FBFBFB"}
              >
                <i className={`ph-light ${a.icon}`} style={{fontSize:"16px"}}/>
              </button>
            ))}
          </div>
        </div>

        {/* Messages */}
        <div style={{flex:1,overflowY:"auto",padding:"24px 24px",display:"flex",flexDirection:"column",gap:"12px"}}>
          {/* Label date première session */}
          <div style={{textAlign:"center",margin:"8px 0"}}>
            <span style={{background:"#EAEEF0",borderRadius:"999px",padding:"4px 12px",fontSize:"12px",color:"#587A89",fontWeight:500}}>
              {sel.messages[0]?.time.split("·")[0].trim() ?? ""}
            </span>
          </div>

          {sel.messages.map((m,i)=>{
            const isMe = m.from==="me";
            const showDate = i>0 && sel.messages[i].time.split("·")[0] !== sel.messages[i-1].time.split("·")[0];
            return (
              <React.Fragment key={m.id}>
                {showDate&&(
                  <div style={{textAlign:"center",margin:"4px 0"}}>
                    <span style={{background:"#EAEEF0",borderRadius:"999px",padding:"4px 12px",fontSize:"12px",color:"#587A89",fontWeight:500}}>
                      {m.time.split("·")[0].trim()}
                    </span>
                  </div>
                )}
                <div style={{display:"flex",flexDirection:isMe?"row-reverse":"row",gap:"8px",alignItems:"flex-end",maxWidth:"80%",alignSelf:isMe?"flex-end":"flex-start"}}>
                  {!isMe&&(
                    <div style={{width:"30px",height:"30px",borderRadius:"50%",background:sel.couleur,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"12px",fontWeight:700,color:"#FFFFFF",flexShrink:0}}>
                      {sel.initiales}
                    </div>
                  )}
                  <div style={{maxWidth:"420px"}}>
                    <div style={{
                      background:isMe?C.secondary:"#FFFFFF",
                      color:isMe?"#FFFFFF":C.primary,
                      borderRadius:isMe?"16px 16px 4px 16px":"16px 16px 16px 4px",
                      padding:"12px 16px",
                      fontSize:"14px",
                      lineHeight:"1.5",
                      border:isMe?"none":"1px solid #EAEEF0",
                      boxShadow:isMe?"none":"0 1px 2px rgba(0,0,0,0.04)",
                    }}>
                      {m.text}
                    </div>
                    <div style={{display:"flex",alignItems:"center",gap:"4px",marginTop:"4px",justifyContent:isMe?"flex-end":"flex-start"}}>
                      <span style={{fontSize:"10px",color:"#9FB3BB"}}>{m.time.split("·")[1]?.trim()}</span>
                      {isMe&&<i className={`ph-fill ${m.read?"ph-checks":"ph-check"}`} style={{fontSize:"12px",color:m.read?"#2E596B":"#9FB3BB"}}/>}
                    </div>
                  </div>
                </div>
              </React.Fragment>
            );
          })}
        </div>

        {/* Zone de saisie */}
        <div style={{padding:"12px 16px",borderTop:"1px solid #EAEEF0",background:"#FFFFFF",flexShrink:0}}>
          {/* Actions rapides */}
          <div style={{display:"flex",gap:"8px",marginBottom:"12px",overflowX:"auto",paddingBottom:"2px"}}>
            {["📅 Proposer un RDV","📎 Joindre un document","📋 Insérer un modèle","🔔 Demande urgente"].map(s=>(
              <button key={s} onClick={()=>setDraft(d=>d?d+" "+s:s)} style={{flexShrink:0,padding:"4px 12px",borderRadius:"999px",border:"1px solid #EAEEF0",background:"#FBFBFB",fontSize:"12px",color:"#2A5161",cursor:"pointer",whiteSpace:"nowrap",fontWeight:500,transition:"all 0.15s"}}
                onMouseEnter={e=>(e.currentTarget as HTMLElement).style.background="#EAEEF0"}
                onMouseLeave={e=>(e.currentTarget as HTMLElement).style.background="#FBFBFB"}
              >{s}</button>
            ))}
          </div>
          {/* Champ saisie */}
          <div style={{display:"flex",gap:"12px",alignItems:"flex-end"}}>
            <div style={{flex:1,border:"1px solid #EAEEF0",borderRadius:"12px",padding:"12px 16px",background:"#FBFBFB",display:"flex",alignItems:"flex-end",gap:"8px"}}>
              <textarea
                value={draft}
                onChange={e=>setDraft(e.target.value)}
                onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendMsg();}}}
                placeholder="Écrire un message… (Entrée pour envoyer, Maj+Entrée pour sauter une ligne)"
                style={{flex:1,border:"none",background:"transparent",resize:"none",outline:"none",fontSize:"14px",color:C.primary,fontFamily:"Inter,sans-serif",lineHeight:"1.5",minHeight:"22px",maxHeight:"120px"}}
                rows={1}
              />
              <div style={{display:"flex",gap:"8px",flexShrink:0}}>
                <button title="Emoji" style={{border:"none",background:"transparent",cursor:"pointer",padding:"2px",color:"#9FB3BB",fontSize:"20px"}}>
                  <i className="ph-light ph-smiley" style={{fontSize:"20px"}}/>
                </button>
                <button title="Pièce jointe" style={{border:"none",background:"transparent",cursor:"pointer",padding:"2px",color:"#9FB3BB"}}>
                  <i className="ph-light ph-paperclip" style={{fontSize:"20px"}}/>
                </button>
              </div>
            </div>
            <button
              onClick={sendMsg}
              disabled={!draft.trim()}
              style={{width:"42px",height:"42px",borderRadius:"50%",border:"none",background:draft.trim()?C.secondary:"#EAEEF0",cursor:draft.trim()?"pointer":"default",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,transition:"all 0.2s"}}
            >
              <i className="ph-fill ph-paper-plane-tilt" style={{fontSize:"20px",color:draft.trim()?"#FFFFFF":"#9FB3BB"}}/>
            </button>
          </div>
          <div style={{fontSize:"10px",color:"#9FB3BB",marginTop:"8px",textAlign:"center"}}>
            Les messages envoyés sont notifiés par email aux intervenants · Chiffrement de bout en bout
          </div>
        </div>
      </div>
    </div>
  );
}


