  const addAccomp = () => {
    const id = "acc-"+Date.now();
    const initials = newAccomp.nom.split(" ").map(w=>w[0]||"").join("").slice(0,2).toUpperCase();
    const colors=["#213F4C","#7A00B3","#587A89","#D32F2F","#F7922B","#811D1D","#225725","#2A5161","#015F92","#6A009C"];
    const randColor=colors[Math.floor(Math.random()*colors.length)];
    setPool(ps=>[...ps,{...newAccomp,id,avatar:initials,avatarColor:randColor}]);
    setNewAccomp({nom:"",organisation:"",email:"",role:"",statut:"invite",produits:[],avatar:""});
    setShowAddAccomp(false);
  };
