  const sendMessage = (demandeId:string) => {
    if(!newMessage.trim()) return;
    setDemandes(ds=>ds.map(d=>d.id===demandeId?{...d,messages:[...d.messages,{
      auteur:"Conseiller CEMP", date:new Date().toLocaleDateString("fr-FR")+" "+new Date().toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"}),
      texte:newMessage.trim(), type:"banque" as const
    }]}:d));
    setNewMessage("");
  };
  const updateAFStatut = (demandeId:string, afId:string, statut:AppelStatut) => {
    setDemandes(ds=>ds.map(d=>d.id===demandeId?{...d,appelsFonds:(d.appelsFonds||[]).map(af=>af.id===afId?{...af,statut,dateVersement:statut==="valide_verse"?new Date().toLocaleDateString("fr-FR"):af.dateVersement}:af)}:d));
    setSelectedAF(null);
  };
  const updateStatutDemande = (id:string, statut:DemandeStatut) => {
    setDemandes(ds=>ds.map(d=>d.id===id?{...d,statut}:d));
  };

