  // ── LaCoprCopro — Carte d'identité seule (vue copropriétaire) ────────────
  const LaCoprCopro = () => {
    const [csub, setCsub] = useState<"accueil">("accueil");
    const fiche = COPRO_FICHE_INIT;
    const kpis = [
      {icon:"ph-map-pin",     label:"Adresse",        value:COPRO.adresse},
      {icon:"ph-calendar",    label:"Construction",   value:String(fiche.anneeConstruction)},
      {icon:"ph-buildings",   label:"Lots",           value:String(COPRO.lots)+" lots"},
      {icon:"ph-ruler",       label:"Surface",        value:BATIMENT.surface+" m²"},
      {icon:"ph-stairs",      label:"Niveaux",        value:String(BATIMENT.niveaux)+" niveaux"},
      {icon:"ph-thermometer", label:"Chauffage",      value:fiche.typeChauffage},
      {icon:"ph-wind",        label:"Ventilation",    value:fiche.typeVMC},
      {icon:"ph-drop",        label:"ECS",            value:fiche.typeECS},
    ];
    return(
      <div style={{padding:"24px 32px",overflowY:"auto",height:"100%",boxSizing:"border-box"}}>
        <div style={{marginBottom:"24px",display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:"12px"}}>
          <div>
            <h4 style={{margin:"0 0 4px",fontWeight:700,color:C.primary,fontSize:"20px",fontFamily:"Montserrat,sans-serif"}}>La Copropriété</h4>
            <p style={{margin:0,color:"#587A89",fontSize:"14px"}}>{COPRO.nom} · {COPRO.adresse}</p>
          </div>
          <span style={{background:"#F3F9EC",color:"#388E3C",borderRadius:"4px",padding:"4px 12px",fontSize:"12px",fontWeight:700,border:"1px solid #ADD1AF"}}>
            <i className="ph-light ph-eye" style={{marginRight:"4px"}}/>Lecture seule
          </span>
        </div>

        {/* Carte d'identité */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(320px,1fr))",gap:"16px",marginBottom:"24px"}}>
          {/* Identité principale */}
          <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"24px",gridColumn:"span 2"}}>
            <div style={{display:"flex",alignItems:"center",gap:"12px",marginBottom:"16px",borderBottom:"1px solid #F2F3F4",paddingBottom:"12px"}}>
              <i className="ph-light ph-identification-card" style={{fontSize:"20px",color:C.secondary}}/>
              <span style={{fontWeight:700,color:"#13252D",fontSize:"14px"}}>Carte d'identité</span>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))",gap:"12px"}}>
              {kpis.map(k=>(
                <div key={k.label} style={{display:"flex",alignItems:"flex-start",gap:"12px",padding:"12px 12px",background:"#FBFBFB",borderRadius:"8px"}}>
                  <div style={{width:"30px",height:"30px",borderRadius:"4px",background:C.secondary+"15",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                    <i className={`ph-light ${k.icon}`} style={{fontSize:"14px",color:C.secondary}}/>
                  </div>
                  <div>
                    <div style={{fontSize:"10px",color:"#9FB3BB",fontWeight:700,marginBottom:"2px"}}>{k.label}</div>
                    <div style={{fontSize:"12px",fontWeight:600,color:"#19313B"}}>{k.value}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Syndic */}
          <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
            <div style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"16px",borderBottom:"1px solid #F2F3F4",paddingBottom:"12px"}}>
              <i className="ph-light ph-buildings" style={{fontSize:"16px",color:"#2A5161"}}/>
              <span style={{fontWeight:700,color:"#13252D",fontSize:"14px"}}>Syndic</span>
            </div>
            {[
              ["Cabinet",fiche.syndic],["Gestionnaire",fiche.gestionnaire],
              ["Tél.",fiche.telSyndic],["Email",fiche.emailSyndic],
            ].map(([l,v])=>(
              <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"4px 0",borderBottom:"1px solid #FBFBFB",fontSize:"12px"}}>
                <span style={{color:"#587A89"}}>{l}</span>
                <span style={{fontWeight:600,color:"#19313B"}}>{v}</span>
              </div>
            ))}
          </div>

          {/* Conseil syndical */}
          <div style={{background:"#FBFBFB",border:"1px solid #C3C5C7",borderRadius:"8px",padding:"16px"}}>
            <div style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"16px",borderBottom:"1px solid #F2F3F4",paddingBottom:"12px"}}>
              <i className="ph-light ph-users-three" style={{fontSize:"16px",color:"#7A00B3"}}/>
              <span style={{fontWeight:700,color:"#13252D",fontSize:"14px"}}>Conseil syndical</span>
            </div>
            {[
              ["Président","M. Philippe Fontaine"],
              ["Secrétaire","Mme Isabelle Leclercq"],
              ["Trésorier","M. Patrick Dufour"],
              ["Tél. référent","06 56 78 90 12"],
            ].map(([l,v])=>(
              <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"4px 0",borderBottom:"1px solid #FBFBFB",fontSize:"12px"}}>
                <span style={{color:"#587A89"}}>{l}</span>
                <span style={{fontWeight:600,color:"#19313B"}}>{v}</span>
              </div>
            ))}
          </div>

          {/* Votre lot */}
          <div style={{background:"#F3F9EC",border:"1px solid #F7EBB7",borderRadius:"12px",padding:"16px"}}>
            <div style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"16px",borderBottom:"1px solid #F7EBB7",paddingBottom:"12px"}}>
              <i className="ph-light ph-house-line" style={{fontSize:"16px",color:"#AC5700"}}/>
              <span style={{fontWeight:700,color:"#13252D",fontSize:"14px"}}>Votre lot</span>
            </div>
            {[
              ["Nom",VDBERG.nom],
              ["Appartement",VDBERG.appt],
              ["Type",VDBERG_LOT.type],
              ["Tantièmes",VDBERG_LOT.t+" / "+COPRO.T+" ("+Math.round(VDBERG_LOT.t/COPRO.T*1000)/10+"‰)"],
              ["Qualification",VDBERG_LOT.qual],
              ["Statut",VDBERG_LOT.statut_lot],
            ].map(([l,v])=>(
              <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"4px 0",borderBottom:"1px solid #FDE68A33",fontSize:"12px"}}>
                <span style={{color:"#954C00"}}>{l}</span>
                <span style={{fontWeight:600,color:"#19313B"}}>{v}</span>
              </div>
            ))}
          </div>

          {/* Projet en cours */}
          <div style={{background:"#EBF4EC",border:"1px solid #ADD1AF",borderRadius:"12px",padding:"16px"}}>
            <div style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"16px",borderBottom:"1px solid #ADD1AF",paddingBottom:"12px"}}>
              <i className="ph-light ph-hammer" style={{fontSize:"16px",color:"#388E3C"}}/>
              <span style={{fontWeight:700,color:"#13252D",fontSize:"14px"}}>Projet de rénovation</span>
            </div>
            {[
              ["DPE actuel","E — 245 kWhEP/m²/an"],
              ["DPE cible","C — 117 kWhEP/m²/an"],
              ["Gain énergétique","-52%"],
              ["Phase en cours","Phase 5 — Réalisation"],
              ["Étape","Suivi des travaux"],
              ["Budget total","290 950 € TTC"],
              ["Votre RAC (cash)",VD_RAC.toLocaleString("fr-FR")+" €"],
            ].map(([l,v])=>(
              <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"4px 0",borderBottom:"1px solid #BBF7D033",fontSize:"12px"}}>
                <span style={{color:"#388E3C"}}>{l}</span>
                <span style={{fontWeight:600,color:"#19313B"}}>{v}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  };




